insert into questions (level, category, question_text, options, correct_option_index, explanation) values
(1, 'logic', 'Ravi is faster than Leo. Leo is faster than Omar. Who is the slowest?', '["Ravi", "Leo", "Omar", "They are equal"]', 2, 'Ravi > Leo > Omar in speed, so Omar is the slowest.'),
(1, 'logic', 'Nina has fewer pencils than Kira. Kira has fewer than Jade. Who has the most pencils?', '["Nina", "Kira", "Jade", "They are equal"]', 2, 'Nina < Kira < Jade, so Jade has the most pencils.'),
(1, 'logic', 'Four kids line up for lunch. Omar is ahead of Priya. Priya is ahead of Wes. Who is at the very back?', '["Omar", "Priya", "Wes", "Cannot tell"]', 2, 'The order front to back is Omar, Priya, Wes, so Wes is at the back.'),
(1, 'logic', 'If today is Saturday, what day will it be in 2 days?', '["Sunday", "Monday", "Tuesday", "Friday"]', 1, 'Saturday + 2 days: Sunday, then Monday.'),
(1, 'logic', 'Today is Thursday. What day was it 3 days ago?', '["Monday", "Tuesday", "Sunday", "Wednesday"]', 0, 'Counting back 3 days from Thursday: Wednesday, Tuesday, Monday.'),
(1, 'logic', 'Tomorrow is Tuesday. What day is today?', '["Sunday", "Monday", "Wednesday", "Tuesday"]', 1, 'If tomorrow is Tuesday, today must be Monday.'),
(1, 'logic', 'All birds have feathers. A robin is a bird. Does a robin have feathers?', '["Yes", "No", "Only in summer", "Cannot tell"]', 0, 'Since all birds have feathers and a robin is a bird, a robin has feathers.'),
(1, 'logic', 'No cats can swim underwater like fish. Whiskers is a cat. Can Whiskers swim underwater like a fish?', '["Yes", "No", "Only baby cats", "Cannot tell"]', 1, 'Since no cats can swim underwater like fish, Whiskers cannot either.'),
(1, 'logic', 'Which number breaks the pattern: 10, 20, 30, 35, 40?', '["20", "35", "30", "40"]', 1, 'All the other numbers are multiples of 10. 35 is not.'),
(1, 'logic', 'Which one does not belong: Red, Blue, Chair, Green?', '["Red", "Blue", "Chair", "Green"]', 2, 'Red, Blue, and Green are colors. Chair is a piece of furniture.'),
(1, 'logic', 'Which one does not belong: Dog, Cat, Rabbit, Shoe?', '["Dog", "Cat", "Rabbit", "Shoe"]', 3, 'Dog, Cat, and Rabbit are animals. A shoe is not.'),
(1, 'logic', 'If it is cold outside, Dad wears a jacket. It is cold outside right now. What does Dad wear?', '["A jacket", "Shorts", "Sandals", "Nothing"]', 0, 'The rule says cold means Dad wears a jacket, and it is cold, so he wears a jacket.'),
(1, 'logic', 'What comes next in the pattern: Star, Moon, Star, Moon, ___?', '["Sun", "Star", "Cloud", "Moon"]', 1, 'The pattern alternates Star, Moon, so after Moon comes Star again.'),
(1, 'logic', 'What comes next: 2, 4, 6, 8, ___?', '["9", "10", "11", "12"]', 1, 'Each number increases by 2, so after 8 comes 10.'),
(1, 'logic', 'Box X is heavier than Box Y. Box Y is heavier than Box Z. Which box is the heaviest?', '["Box X", "Box Y", "Box Z", "They weigh the same"]', 0, 'X > Y > Z in weight, so Box X is the heaviest.'),
(1, 'logic', 'Mona never lies. Mona says, "My shoes are red." Are her shoes red?', '["Yes", "No", "Cannot tell", "Only sometimes"]', 0, 'Since Mona never lies, what she says must be true, so her shoes are red.'),
(1, 'logic', 'Which one is not a vegetable: Carrot, Peas, Cookie, Broccoli?', '["Carrot", "Peas", "Cookie", "Broccoli"]', 2, 'Carrot, Peas, and Broccoli are vegetables. A cookie is not.'),
(1, 'logic', 'Which one is not a bird: Sparrow, Eagle, Dolphin, Parrot?', '["Sparrow", "Eagle", "Dolphin", "Parrot"]', 2, 'Sparrow, Eagle, and Parrot are birds. A dolphin is a sea animal, not a bird.'),
(1, 'logic', 'What comes next in the pattern: 1, 3, 5, 7, ___?', '["8", "9", "10", "11"]', 1, 'Each number increases by 2 (odd numbers), so after 7 comes 9.'),
(1, 'logic', 'Five friends stand in a row. Diya is in front of Ravi. Ravi is in front of Sana. Who is closest to the front?', '["Diya", "Ravi", "Sana", "Cannot tell"]', 0, 'The order from front is Diya, Ravi, Sana, so Diya is closest to the front.'),
(1, 'logic', 'All fish live in water. Goldie is a fish. Does Goldie live in water?', '["Yes", "No", "Only in winter", "Cannot tell"]', 0, 'Since all fish live in water and Goldie is a fish, Goldie lives in water.'),
(1, 'logic', 'If a shape has 3 sides, it is a triangle. This shape has 3 sides. What shape is it?', '["A square", "A triangle", "A circle", "A pentagon"]', 1, 'The rule says 3 sides means a triangle, so this shape is a triangle.'),
(1, 'logic', 'Which number is missing: 5, 10, ___, 20, 25?', '["12", "15", "18", "14"]', 1, 'Counting up by 5 each time, the missing number between 10 and 20 is 15.'),
(1, 'logic', 'Which one does not belong: Monday, Tuesday, Summer, Friday?', '["Monday", "Tuesday", "Summer", "Friday"]', 2, 'Monday, Tuesday, and Friday are days of the week. Summer is a season.'),
(1, 'logic', 'Which one does not belong: Red, Yellow, Circle, Blue?', '["Red", "Yellow", "Circle", "Blue"]', 2, 'Red, Yellow, and Blue are colors. Circle is a shape, not a color.'),
(1, 'logic', 'Tia is shorter than Zoe. Zoe is shorter than Wren. Who is the tallest?', '["Tia", "Zoe", "Wren", "They are equal"]', 2, 'Tia < Zoe < Wren in height, so Wren is the tallest.'),
(1, 'logic', 'Four runners finish a race. Kabir finishes before Lena. Lena finishes before Milo. Who finishes first?', '["Kabir", "Lena", "Milo", "Cannot tell"]', 0, 'The finishing order is Kabir, Lena, Milo, so Kabir finishes first.'),
(1, 'logic', 'Yesterday was Sunday. What day is today?', '["Saturday", "Sunday", "Monday", "Tuesday"]', 2, 'If yesterday was Sunday, today is Monday.'),
(1, 'logic', 'Today is Tuesday. What day will it be in 5 days?', '["Saturday", "Sunday", "Friday", "Monday"]', 1, 'Counting forward 5 days from Tuesday lands on Sunday.'),
(1, 'logic', 'All ducks can swim. Quacker is a duck. Can Quacker swim?', '["Yes", "No", "Only in summer", "Cannot tell"]', 0, 'Since all ducks can swim and Quacker is a duck, Quacker can swim.'),
(1, 'logic', 'Which number breaks the pattern: 3, 6, 9, 11, 12?', '["9", "11", "12", "6"]', 1, 'All the other numbers are multiples of 3. 11 is not.'),
(1, 'logic', 'Which one does not belong: Piano, Guitar, Drum, Ball?', '["Piano", "Guitar", "Drum", "Ball"]', 3, 'Piano, Guitar, and Drum are musical instruments. A ball is not.'),
(1, 'logic', 'If the light is red, cars must stop. The light is red right now. What must cars do?', '["Go faster", "Stop", "Turn around", "Honk"]', 1, 'The rule says red means stop, and the light is red, so cars must stop.'),
(1, 'logic', 'What comes next in the pattern: Big, Small, Big, Small, ___?', '["Big", "Medium", "Tiny", "Huge"]', 0, 'The pattern alternates Big, Small, so after Small comes Big again.'),
(1, 'logic', 'What comes next: 20, 18, 16, 14, ___?', '["13", "12", "10", "11"]', 1, 'Each number decreases by 2, so after 14 comes 12.'),
(1, 'logic', 'Rope A is longer than Rope B. Rope B is longer than Rope C. Which rope is the shortest?', '["Rope A", "Rope B", "Rope C", "They are equal"]', 2, 'A > B > C in length, so Rope C is the shortest.'),
(1, 'logic', 'Kiran never breaks a promise. Kiran promises to be at the park at 3pm. Will Kiran be at the park at 3pm?', '["Yes", "No", "Cannot tell", "Only if it does not rain"]', 0, 'Since Kiran never breaks a promise, Kiran will keep the promise to be at the park at 3pm.'),
(1, 'logic', 'Which one is not a drink: Juice, Milk, Bread, Water?', '["Juice", "Milk", "Bread", "Water"]', 2, 'Juice, Milk, and Water are drinks. Bread is a food, not a drink.'),
(1, 'logic', 'Which one is not an insect: Ant, Bee, Spider, Butterfly?', '["Ant", "Bee", "Spider", "Butterfly"]', 2, 'Ant, Bee, and Butterfly are insects. A spider has 8 legs and is not an insect.'),
(1, 'logic', 'What comes next in the pattern: 100, 90, 80, 70, ___?', '["50", "60", "65", "75"]', 1, 'Each number decreases by 10, so after 70 comes 60.'),
(1, 'logic', 'Six kids line up by height for a photo. Elin is shorter than Fay. Fay is shorter than Gus. Who is the tallest of these three?', '["Elin", "Fay", "Gus", "Cannot tell"]', 2, 'Elin < Fay < Gus in height, so Gus is the tallest.'),
(1, 'logic', 'All squares have 4 sides. This shape is a square. How many sides does it have?', '["3", "4", "5", "6"]', 1, 'Since all squares have 4 sides and this shape is a square, it has 4 sides.'),
(1, 'logic', 'If Mia finishes her homework, she gets to watch TV. Mia finished her homework. What does Mia get to do?', '["Watch TV", "Go to bed", "Clean her room", "Nothing"]', 0, 'The rule says finishing homework means watching TV, and Mia finished, so she gets to watch TV.'),
(1, 'logic', 'Which number is missing: 2, 4, 6, ___, 10?', '["7", "8", "9", "11"]', 1, 'Counting up by 2 each time, the missing number between 6 and 10 is 8.'),
(1, 'logic', 'Which one does not belong: Swimming, Running, Jumping, Pencil?', '["Swimming", "Running", "Jumping", "Pencil"]', 3, 'Swimming, Running, and Jumping are all activities. A pencil is an object, not an activity.'),
(1, 'logic', 'Which one does not belong: January, March, Tuesday, July?', '["January", "March", "Tuesday", "July"]', 2, 'January, March, and July are months. Tuesday is a day of the week.'),
(1, 'logic', 'A week has 7 days. Today is the 3rd day of the week (counting Monday as day 1). What day is it?', '["Sunday", "Tuesday", "Wednesday", "Thursday"]', 2, 'Counting Monday as day 1, day 3 is Wednesday.'),
(1, 'logic', 'Eight kids are in a line for the slide. Zane is 3rd. How many kids are in front of Zane?', '["1", "2", "3", "4"]', 1, 'If Zane is 3rd in line, there are 2 kids ahead of him (1st and 2nd).'),
(1, 'logic', 'All squares are also rectangles. This shape is NOT a rectangle. Could it be a square?', '["Yes", "No", "Only sometimes", "Cannot tell"]', 1, 'Since every square must be a rectangle, a shape that is not a rectangle cannot be a square.'),
(1, 'logic', 'Which comes next in the pattern: Monday, Wednesday, Friday, ___?', '["Saturday", "Sunday", "Tuesday", "Thursday"]', 1, 'Each day in the pattern skips one day ahead, so after Friday comes Sunday.');
insert into questions (level, category, question_text, options, correct_option_index, explanation) values
(1, 'riddle', 'What opens up to keep you dry, but folds up small to fit in your bag?', '["Umbrella", "Raincoat", "Tent", "Boot"]', 0, 'An umbrella opens wide to block the rain and folds up small to carry.'),
(1, 'riddle', 'What melts away a little every time you light it?', '["Candle", "Ice cube", "Chocolate", "Crayon"]', 0, 'A candle slowly melts down each time it burns.'),
(1, 'riddle', 'What covers your foot and often has laces, but is not a sock?', '["Shoe", "Sock", "Glove", "Hat"]', 0, 'A shoe covers your foot and usually has laces to tie; a sock does not.'),
(1, 'riddle', 'What has a front cover, a back cover, and pages full of one story in between?', '["Book", "Box", "Folder", "Envelope"]', 0, 'A book has a front and back cover with pages of a story between them.'),
(1, 'riddle', 'You knock on it before entering a room, and it always has a handle or knob. What is it?', '["Door", "Window", "Wall", "Floor"]', 0, 'You knock on a door before entering, and it always has a handle or knob to open it.'),
(1, 'riddle', 'What can cook your food and keep you warm, but will hurt you if you touch it?', '["Fire", "Ice", "Water", "Wind"]', 0, 'Fire cooks food and warms you, but touching the flame will burn you.'),
(1, 'riddle', 'What is soft, white, cold, and lets you build a snowman when it piles up?', '["Snow", "Rain", "Fog", "Frost"]', 0, 'Snow is the soft, white, cold stuff that piles up so you can build a snowman.'),
(1, 'riddle', 'What follows you everywhere on a sunny day, but disappears when the sun goes down?', '["Shadow", "Reflection", "Echo", "Footprint"]', 0, 'Your shadow is made by blocking sunlight, so it follows you in the sun and disappears at night.'),
(1, 'riddle', 'What is a giant, rocky landform so tall that people climb it for days to reach the top?', '["Mountain", "Hill", "Cliff", "Volcano"]', 0, 'A mountain is an especially tall, rocky landform that can take days to climb to the top.'),
(1, 'riddle', 'What has roots, a trunk, and leaves, and grows taller every year?', '["Tree", "Flower", "Bush", "Grass"]', 0, 'A tree has a trunk, roots, and leaves, and grows taller as it ages.'),
(1, 'riddle', 'What do you slide a letter into before mailing it, and it needs a stamp to travel?', '["Envelope", "Mailbox", "Postcard", "Package"]', 0, 'A letter goes inside an envelope, which gets a stamp before being mailed.'),
(1, 'riddle', 'What is small, round, made of metal, and used to pay for things?', '["Coin", "Button", "Ring", "Sticker"]', 0, 'A coin is small, round, made of metal, and used as money.'),
(1, 'riddle', 'What shows you roads and places, but you cannot actually walk on any of them?', '["Map", "Globe", "Photograph", "Painting"]', 0, 'A map shows roads and places on paper, but you cannot really walk on the drawing itself.'),
(1, 'riddle', 'What has black and white keys, but you play music instead of typing words?', '["Piano", "Computer keyboard", "Typewriter", "Calculator"]', 0, 'A piano has black and white keys you press to make music, unlike a computer keyboard.'),
(1, 'riddle', 'What do you write with on a blackboard, and it leaves white dust on your fingers?', '["Chalk", "Pencil", "Marker", "Crayon"]', 0, 'Chalk is used to write on blackboards and leaves powdery white dust on your hands.'),
(1, 'riddle', 'What shows you your own face, but everything in it is flipped left to right?', '["Mirror", "Photograph", "Window", "Painting"]', 0, 'A mirror reflects your face, but left and right appear swapped.'),
(1, 'riddle', 'What can you feel and hear, but never actually see with your eyes?', '["Wind", "Sound", "Fire", "Smell"]', 0, 'Wind can be felt on your skin and heard rustling, but it has no visible form.'),
(1, 'riddle', 'What floats in the sky, is fluffy and gray or white, and can bring rain?', '["Cloud", "Kite", "Balloon", "Bird"]', 0, 'Clouds float in the sky and can turn gray and release rain.'),
(1, 'riddle', 'What has many colors in an arch shape, and appears after it rains when the sun comes out?', '["Rainbow", "Sunset", "Cloud", "Kite"]', 0, 'A rainbow is a colorful arch that appears when sunlight shines through rain.'),
(1, 'riddle', 'What twinkles in the night sky and is actually a giant, glowing ball of gas far away?', '["Star", "Moon", "Planet", "Firefly"]', 0, 'Stars are enormous, glowing balls of gas that twinkle from far away in space.'),
(1, 'riddle', 'What changes shape in the sky every night, from a thin sliver to a full circle?', '["Moon", "Sun", "Cloud", "Star"]', 0, 'The moon appears to change shape (its phases) as it orbits Earth each month.'),
(1, 'riddle', 'What is a giant star that gives Earth its light and warmth during the day?', '["Sun", "Moon", "Star", "Lightbulb"]', 0, 'The Sun is the star that lights and warms the Earth during the day.'),
(1, 'riddle', 'What is frozen and slippery, and turns back into water when it warms up?', '["Ice", "Snow", "Glass", "Glue"]', 0, 'Ice is frozen water; it melts back into water when it gets warm.'),
(1, 'riddle', 'What has many layers, and can make you cry when you cut it?', '["Onion", "Cabbage", "Garlic", "Lettuce"]', 0, 'Cutting an onion releases a gas that makes your eyes water.'),
(1, 'riddle', 'What do you hit with sticks or your hands to make a beat?', '["Drum", "Piano", "Guitar", "Flute"]', 0, 'A drum is played by hitting it with sticks or hands to create a rhythm.'),
(1, 'riddle', 'What rings loudly to tell you school has started or class has ended?', '["Bell", "Whistle", "Alarm clock", "Horn"]', 0, 'A bell rings to signal the start or end of class at school.'),
(1, 'riddle', 'What is small, metal, and you turn it to lock or unlock a door?', '["Key", "Coin", "Screw", "Nail"]', 0, 'A key is turned in a lock to open or close a door.'),
(1, 'riddle', 'What keeps a door shut tight until you open it with the right key?', '["Lock", "Hinge", "Handle", "Chain"]', 0, 'A lock keeps a door securely shut until the matching key opens it.'),
(1, 'riddle', 'What has rungs to climb, and helps you reach something high up?', '["Ladder", "Staircase", "Rope", "Chair"]', 0, 'A ladder has rungs you climb to reach high places.'),
(1, 'riddle', 'What is built over a river or road so people and cars can cross safely?', '["Bridge", "Tunnel", "Dam", "Fence"]', 0, 'A bridge is built over water or roads so people and vehicles can cross.'),
(1, 'riddle', 'What spins around to blow air and cool you down on a hot day?', '["Fan", "Air conditioner", "Umbrella", "Kite"]', 0, 'A fan has spinning blades that blow air to cool you off.'),
(1, 'riddle', 'What do you wear on your head to keep the sun off or keep warm?', '["Hat", "Scarf", "Glove", "Sock"]', 0, 'A hat is worn on your head for sun protection or warmth.'),
(1, 'riddle', 'What do you wear on your foot, under your shoe, to keep it warm and cozy?', '["Sock", "Shoe", "Glove", "Mitten"]', 0, 'A sock is worn on your foot, underneath your shoe, to keep it warm.'),
(1, 'riddle', 'What has bristles and a long handle, used for sweeping the floor?', '["Broom", "Mop", "Vacuum", "Rake"]', 0, 'A broom has bristles on a long handle for sweeping up dirt.'),
(1, 'riddle', 'What has a handle on top and can carry water or sand?', '["Bucket", "Basket", "Bag", "Box"]', 0, 'A bucket has a handle and can carry water, sand, or other things.'),
(1, 'riddle', 'What is a deep hole in the ground that people used to get water from long ago?', '["Well", "Cave", "Pond", "Tunnel"]', 0, 'A well is a deep hole dug to reach underground water.'),
(1, 'riddle', 'What flies high in the sky on a string, and needs wind to stay up?', '["Kite", "Balloon", "Airplane", "Bird"]', 0, 'A kite flies on a string and needs wind to stay in the air.'),
(1, 'riddle', 'What is round, see-through, floats in the air, and pops if you touch it?', '["Bubble", "Balloon", "Soap", "Cloud"]', 0, 'A soap bubble is round and see-through, and pops easily when touched.'),
(1, 'riddle', 'What do you rub on your hands with water to wash away dirt and germs?', '["Soap", "Towel", "Sponge", "Lotion"]', 0, 'Soap is rubbed with water on your hands to clean away dirt and germs.'),
(1, 'riddle', 'What repeats your voice back to you when you shout in a big empty space, like a canyon?', '["Echo", "Whisper", "Shadow", "Reflection"]', 0, 'An echo is your own sound bouncing back to you off of something like canyon walls.'),
(1, 'riddle', 'What has 26 letters in a row, from A to Z?', '["Alphabet", "Dictionary", "Keyboard", "Calendar"]', 0, 'The alphabet is the set of 26 letters from A to Z.'),
(1, 'riddle', 'What is one flat sheet inside a book, with a number printed at the bottom or corner?', '["Page", "Cover", "Chapter", "Bookmark"]', 0, 'A page is one sheet inside a book, usually numbered.'),
(1, 'riddle', 'What do you switch on to make light in the dark, and it usually needs batteries?', '["Flashlight", "Candle", "Lamp", "Match"]', 0, 'A flashlight uses batteries to switch on and light up the dark.'),
(1, 'riddle', 'What has steps going up and down, connecting one floor of a house to another?', '["Staircase", "Ladder", "Elevator", "Ramp"]', 0, 'A staircase has steps that connect different floors of a building.'),
(1, 'riddle', 'What is made of glass, lets light into a room, and you can open it for fresh air?', '["Window", "Door", "Mirror", "Wall"]', 0, 'A window is a glass opening that lets in light and can be opened for air.'),
(1, 'riddle', 'What is a tall pipe on a roof that lets smoke escape from a fireplace?', '["Chimney", "Pipe", "Roof", "Fireplace"]', 0, 'A chimney is the pipe on a roof that carries smoke away from a fireplace.'),
(1, 'riddle', 'What is a small pool of water that forms on the ground after it rains?', '["Puddle", "Pond", "Lake", "Ocean"]', 0, 'A puddle is a small, shallow pool of water left after rain.'),
(1, 'riddle', 'What floats on water and carries people from one place to another across a lake or river?', '["Boat", "Car", "Airplane", "Bicycle"]', 0, 'A boat floats on water and carries people across lakes, rivers, or seas.'),
(1, 'riddle', 'What waves in the wind on a pole, and often has colors representing a country?', '["Flag", "Kite", "Banner", "Balloon"]', 0, 'A flag waves on a pole and represents a country or group with its colors.'),
(1, 'riddle', 'What do you sharpen to a point and use to write or draw, often with an eraser on the end?', '["Pencil", "Crayon", "Marker", "Chalk"]', 0, 'A pencil is sharpened to a point for writing or drawing and often has an eraser.');
insert into questions (level, category, question_text, options, correct_option_index, explanation) values
(1, 'spatial', 'How many sides does an octagon have?', '["6", "7", "8", "9"]', 2, 'An octagon has 8 sides.'),
(1, 'spatial', 'How many corners does a square have?', '["3", "4", "5", "6"]', 1, 'A square has 4 corners.'),
(1, 'spatial', 'How many corners does a pentagon have?', '["4", "5", "6", "7"]', 1, 'A pentagon has 5 corners, matching its 5 sides.'),
(1, 'spatial', 'How many corners does a hexagon have?', '["5", "6", "7", "8"]', 1, 'A hexagon has 6 corners, matching its 6 sides.'),
(1, 'spatial', 'Which shape is completely round with no corners at all?', '["Square", "Circle", "Triangle", "Rectangle"]', 1, 'A circle is perfectly round and has no corners.'),
(1, 'spatial', 'Which shape looks like a squashed circle, longer in one direction?', '["Circle", "Oval", "Square", "Triangle"]', 1, 'An oval (or ellipse) is like a stretched-out circle.'),
(1, 'spatial', 'Which shape has 4 slanted sides that are all equal, like a tilted square?', '["Rhombus", "Circle", "Triangle", "Pentagon"]', 0, 'A rhombus has 4 equal sides that are slanted, like a diamond shape.'),
(1, 'spatial', 'If you are facing East and turn left, which direction do you face?', '["North", "South", "West", "East"]', 0, 'Turning left (counter-clockwise) from East faces North.'),
(1, 'spatial', 'If you are facing West and turn right, which direction do you face?', '["South", "North", "East", "West"]', 1, 'Turning right (clockwise) from West faces North.'),
(1, 'spatial', 'If you are facing South and turn left twice, which direction do you face?', '["South", "North", "East", "West"]', 1, 'Turning left once from South faces East; turning left again faces North.'),
(1, 'spatial', 'If you are facing North and turn right twice, which direction do you face?', '["North", "South", "East", "West"]', 1, 'Turning right once from North faces East; turning right again faces South.'),
(1, 'spatial', 'On a map with North at the top, which direction is on the right side?', '["North", "South", "East", "West"]', 2, 'When North is at the top of a map, East is on the right side.'),
(1, 'spatial', 'On a map with North at the top, which direction is on the left side?', '["North", "South", "East", "West"]', 3, 'When North is at the top of a map, West is on the left side.'),
(1, 'spatial', 'Which is bigger: a triangle with 5 cm sides, or a triangle with 3 cm sides?', '["The 5 cm triangle", "The 3 cm triangle", "They are the same size", "Cannot tell"]', 0, 'Longer sides make a bigger triangle, so the 5 cm triangle is larger.'),
(1, 'spatial', 'Which is smaller: a circle with a 2 cm width, or a circle with an 8 cm width?', '["The 2 cm circle", "The 8 cm circle", "They are the same size", "Cannot tell"]', 0, 'A smaller width means a smaller circle, so the 2 cm circle is smaller.'),
(1, 'spatial', 'How many straight sides does a circle have?', '["0", "1", "2", "4"]', 0, 'A circle is one curved line all the way around - it has zero straight sides.'),
(1, 'spatial', 'How many corners does an octagon have?', '["6", "7", "8", "9"]', 2, 'An octagon has 8 corners, matching its 8 sides.'),
(1, 'spatial', 'Which 3D shape looks like a ball and can roll in any direction?', '["Cube", "Sphere", "Cone", "Cylinder"]', 1, 'A sphere is perfectly round like a ball and can roll any which way.'),
(1, 'spatial', 'Which 3D shape looks like a can of soup, with flat circles on the top and bottom?', '["Sphere", "Cube", "Cylinder", "Cone"]', 2, 'A cylinder has two flat circle ends and a curved side, like a soup can.'),
(1, 'spatial', 'Which 3D shape has a flat base and comes to a single point at the top?', '["Cube", "Pyramid", "Cylinder", "Sphere"]', 1, 'A pyramid has a flat base and slanted sides that meet at a point on top.'),
(1, 'spatial', 'Which shape has 4 corners and 4 sides that are all the same length?', '["Rectangle", "Square", "Triangle", "Pentagon"]', 1, 'A square has 4 equal sides and 4 equal corners.'),
(1, 'spatial', 'If you are facing East and turn around completely (180 degrees), which direction do you face?', '["North", "South", "East", "West"]', 3, 'Turning all the way around (180 degrees) from East faces the opposite direction, West.'),
(1, 'spatial', 'Which shape has more corners: a square or a hexagon?', '["A square", "A hexagon", "They are equal", "Neither has corners"]', 1, 'A hexagon has 6 corners, while a square only has 4.'),
(1, 'spatial', 'Which shape has fewer sides: a triangle or a rectangle?', '["A triangle", "A rectangle", "They are equal", "Neither has sides"]', 0, 'A triangle has 3 sides, while a rectangle has 4 - so the triangle has fewer.'),
(1, 'spatial', 'Which direction is opposite to South?', '["East", "North", "West", "South"]', 1, 'South and North are opposite directions on a compass.'),
(1, 'spatial', 'If you walk forward while facing North, then turn left, which direction are you now facing?', '["North", "South", "East", "West"]', 3, 'Turning left from North faces West.'),
(1, 'spatial', 'Which shape has exactly 6 sides?', '["Pentagon", "Hexagon", "Heptagon", "Octagon"]', 1, 'A hexagon has exactly 6 sides.'),
(1, 'spatial', 'Which shape has exactly 7 sides?', '["Hexagon", "Heptagon", "Octagon", "Pentagon"]', 1, 'A heptagon has exactly 7 sides.'),
(1, 'spatial', 'A square table has how many corners?', '["3", "4", "5", "6"]', 1, 'A square table has 4 corners, just like any square.'),
(1, 'spatial', 'A cube is placed on a table. How many of its faces are touching the table?', '["1", "2", "3", "4"]', 0, 'Only the bottom face of the cube touches the table - that is 1 face.'),
(1, 'spatial', 'Which shape has 8 equal sides, like a stop sign?', '["Hexagon", "Octagon", "Pentagon", "Square"]', 1, 'A stop sign is shaped like an octagon, with 8 equal sides.'),
(1, 'spatial', 'Which shape is a soccer ball closest to, in 3D?', '["Cube", "Sphere", "Cone", "Pyramid"]', 1, 'A soccer ball is round in every direction, like a sphere.'),
(1, 'spatial', 'Which shape is a party hat closest to, in 3D?', '["Cylinder", "Cone", "Cube", "Sphere"]', 1, 'A party hat is shaped like a cone, with a circular base and a pointed top.'),
(1, 'spatial', 'Which shape is a can of juice closest to, in 3D?', '["Cone", "Sphere", "Cylinder", "Pyramid"]', 2, 'A can of juice is shaped like a cylinder.'),
(1, 'spatial', 'Which shape is a dice (like in board games) closest to, in 3D?', '["Sphere", "Cube", "Cone", "Cylinder"]', 1, 'A dice is shaped like a cube, with 6 square faces.'),
(1, 'spatial', 'If North is up on a map, and you move from the top to the bottom, which direction are you moving?', '["North", "South", "East", "West"]', 1, 'Moving from the top (North) to the bottom of the map means moving South.'),
(1, 'spatial', 'Which has more sides: an octagon or a hexagon?', '["An octagon", "A hexagon", "They are equal", "Neither has sides"]', 0, 'An octagon has 8 sides, while a hexagon has only 6.'),
(1, 'spatial', 'Which shape has the fewest sides of all: triangle, square, pentagon, or hexagon?', '["Triangle", "Square", "Pentagon", "Hexagon"]', 0, 'A triangle has only 3 sides, fewer than square (4), pentagon (5), or hexagon (6).'),
(1, 'spatial', 'Which shape has the most sides of all: triangle, square, pentagon, or hexagon?', '["Triangle", "Square", "Pentagon", "Hexagon"]', 3, 'A hexagon has 6 sides, more than triangle (3), square (4), or pentagon (5).'),
(1, 'spatial', 'How many corners does a rhombus (diamond shape) have?', '["3", "4", "5", "6"]', 1, 'A rhombus has 4 corners, just like a square, but tilted.'),
(1, 'spatial', 'If you walk North and then turn to walk East, what shape does your path make?', '["A straight line", "A right angle (L-shape)", "A circle", "A triangle"]', 1, 'Turning from North to East is a 90-degree turn, making an L-shaped, right-angle path.'),
(1, 'spatial', 'Which is taller: a rectangle that is 10 cm tall, or one that is 4 cm tall?', '["The 10 cm rectangle", "The 4 cm rectangle", "They are the same height", "Cannot tell"]', 0, 'A greater height means a taller rectangle, so the 10 cm one is taller.'),
(1, 'spatial', 'A triangle has 3 sides and a square has 4 sides. How many sides do they have added together?', '["6", "7", "8", "5"]', 1, 'A triangle has 3 sides and a square has 4 sides. 3 + 4 = 7.'),
(1, 'spatial', 'A triangle has 3 corners and a rectangle has 4 corners. How many corners do they have added together?', '["6", "7", "8", "5"]', 1, 'A triangle has 3 corners and a rectangle has 4 corners. 3 + 4 = 7.'),
(1, 'spatial', 'Which shape has no corners and no straight sides?', '["Square", "Triangle", "Circle", "Rectangle"]', 2, 'A circle has no straight sides and no corners at all.'),
(1, 'spatial', 'If you are facing West and turn left, which direction do you face?', '["North", "South", "East", "West"]', 1, 'Turning left (counter-clockwise) from West faces South.'),
(1, 'spatial', 'If you are facing East and turn right, which direction do you face?', '["North", "South", "East", "West"]', 1, 'Turning right (clockwise) from East faces South.'),
(1, 'spatial', 'A window shaped like a square has how many equal sides?', '["3", "4", "5", "6"]', 1, 'A square window has 4 equal sides, like any square.'),
(1, 'spatial', 'Which is longer: a line that is 15 cm, or a line that is 9 cm?', '["The 15 cm line", "The 9 cm line", "They are the same length", "Cannot tell"]', 0, 'A bigger number of centimeters means a longer line, so the 15 cm line is longer.'),
(1, 'spatial', 'Which shape has exactly 4 corners, all of them right angles (90 degrees)?', '["Triangle", "Square", "Pentagon", "Circle"]', 1, 'A square has exactly 4 corners, and each one is a 90-degree right angle.');
insert into questions (level, category, question_text, options, correct_option_index, explanation) values
(2, 'logic', 'In a spelling bee, Farah scored higher than Gavin. Gavin scored higher than Hana. Hana scored higher than Ishaan. Who scored the lowest?', '["Farah", "Gavin", "Hana", "Ishaan"]', 3, 'Farah > Gavin > Hana > Ishaan, so Ishaan scored the lowest.'),
(2, 'logic', 'Four kids are comparing heights. Caleb is shorter than Diya. Diya is shorter than Ethan. Ethan is shorter than Farah. Who is the tallest?', '["Caleb", "Diya", "Ethan", "Farah"]', 3, 'Caleb < Diya < Ethan < Farah in height, so Farah is the tallest.'),
(2, 'logic', 'Block A is heavier than Block B. Block B is heavier than Block C. Block C is heavier than Block D. Which block is the lightest?', '["Block A", "Block B", "Block C", "Block D"]', 3, 'A > B > C > D in weight, so Block D is the lightest.'),
(2, 'logic', 'Five runners cross the finish line in this order: Kabir, then Leah, then Manav, then Nora, then Omar. Who finished 2nd?', '["Kabir", "Leah", "Manav", "Omar"]', 1, 'The finishing order was Kabir, Leah, Manav, Nora, Omar - so Leah finished 2nd.'),
(2, 'logic', 'In a line of six kids, Priti is 3rd from the front. How many kids are standing in front of her?', '["1", "2", "3", "4"]', 1, 'If Priti is 3rd from the front, exactly 2 kids are ahead of her.'),
(2, 'logic', 'In a line of eight kids, Quinn is 3rd from the back. What position is Quinn counting from the front?', '["5th", "6th", "7th", "8th"]', 1, 'With 8 kids total and Quinn 3rd from the back, Quinn is at position 8 - 3 + 1 = 6th from the front.'),
(2, 'logic', 'Riya is taller than Sahil but shorter than Tara. Who is the tallest of the three?', '["Riya", "Sahil", "Tara", "Cannot tell"]', 2, 'Sahil < Riya < Tara in height, so Tara is the tallest.'),
(2, 'logic', 'Uma finished the puzzle faster than Vikram. Vikram finished faster than Wren, who finished faster than Xander. Who finished the puzzle slowest?', '["Uma", "Vikram", "Wren", "Xander"]', 3, 'The speed order is Uma, Vikram, Wren, Xander, so Xander finished slowest.'),
(2, 'logic', 'All maples are trees. All trees need sunlight. Does a maple need sunlight?', '["Yes", "No", "Only in summer", "Cannot tell"]', 0, 'Since all maples are trees, and all trees need sunlight, a maple must need sunlight too.'),
(2, 'logic', 'No reptiles are warm-blooded. A lizard is a reptile. Is a lizard warm-blooded?', '["Yes", "No", "Only some lizards", "Cannot tell"]', 1, 'Since no reptiles are warm-blooded and a lizard is a reptile, a lizard cannot be warm-blooded.'),
(2, 'logic', 'All Wibbles are Zons. No Zons are Yindles. Can a Wibble be a Yindle?', '["Yes", "No", "Only sometimes", "Cannot tell"]', 1, 'Every Wibble is a Zon, and no Zon is a Yindle, so no Wibble can be a Yindle.'),
(2, 'logic', 'Some Plinks are Florps. All Florps are Grendles. Are all Plinks definitely Grendles?', '["Yes, definitely", "No, never", "Cannot be determined", "Only on weekdays"]', 2, 'Only some Plinks are Florps, so the Plinks that are not Florps have no guaranteed link to Grendles - it cannot be determined from these facts alone.'),
(2, 'logic', 'Every student in Room 5 plays an instrument. Noor is in Room 5. Does Noor play an instrument?', '["Yes", "No", "Only if invited", "Cannot tell"]', 0, 'Since every student in Room 5 plays an instrument and Noor is in Room 5, Noor must play one.'),
(2, 'logic', 'No insects have exactly four legs. A ladybug is an insect. Does a ladybug have exactly four legs?', '["Yes", "No", "Only baby ladybugs", "Cannot tell"]', 1, 'Since no insects have exactly four legs and a ladybug is an insect, a ladybug cannot have exactly four legs.'),
(2, 'logic', 'All the coins in the jar are silver. Ben pulls out a coin from the jar without looking. What color is it?', '["Gold", "Silver", "Bronze", "Cannot tell"]', 1, 'Since every coin in the jar is silver, any coin pulled from it must be silver.'),
(2, 'logic', 'Every dog at the shelter has been vaccinated. Rex is a dog at the shelter. Has Rex been vaccinated?', '["Yes", "No", "Only adult dogs", "Cannot tell"]', 0, 'Since every dog at the shelter has been vaccinated and Rex is one of those dogs, Rex has been vaccinated.'),
(2, 'logic', 'What comes next in the pattern: 3, 6, 12, 24, ___?', '["36", "42", "48", "30"]', 2, 'Each number doubles the one before it: 24 x 2 = 48.'),
(2, 'logic', 'What comes next in the pattern: 100, 90, 80, 70, ___?', '["50", "60", "65", "55"]', 1, 'Each number decreases by 10, so after 70 comes 60.'),
(2, 'logic', 'What comes next in the pattern: 2, 5, 10, 17, 26, ___?', '["35", "36", "37", "38"]', 2, 'The gaps between numbers grow by 2 each time (3, 5, 7, 9, 11), so 26 + 11 = 37.'),
(2, 'logic', 'What comes next in the pattern: 1, 4, 9, 16, 25, ___?', '["30", "32", "36", "49"]', 2, 'These are the square numbers (1x1, 2x2, 3x3, 4x4, 5x5), so the next one is 6x6 = 36.'),
(2, 'logic', 'What comes next in the pattern: J, F, M, A, M, ___?', '["J", "A", "S", "O"]', 0, 'These are the first letters of the months in order (January, February, March, April, May), so next comes June: J.'),
(2, 'logic', 'What comes next in the pattern: Z, Y, X, W, ___?', '["U", "V", "T", "S"]', 1, 'The pattern moves backward through the alphabet one letter at a time, so after W comes V.'),
(2, 'logic', 'What comes next in the pattern: 2, 4, 8, 16, ___?', '["24", "30", "32", "36"]', 2, 'Each number doubles the one before it: 16 x 2 = 32.'),
(2, 'logic', 'What number is missing: 5, 10, ___, 20, 25?', '["12", "14", "15", "18"]', 2, 'The numbers increase by 5 each time, so the missing number between 10 and 20 is 15.'),
(2, 'logic', 'If 4 painters can paint 4 walls in 4 hours, how many hours would it take 8 painters to paint 8 walls?', '["2 hours", "4 hours", "8 hours", "16 hours"]', 1, 'Each painter paints 1 wall in 4 hours regardless of how many painters there are, so doubling both painters and walls still takes 4 hours.'),
(2, 'logic', 'A baker can bake 12 cupcakes every 20 minutes. How many cupcakes can the baker bake in 1 hour?', '["24", "30", "36", "40"]', 2, '1 hour is three 20-minute periods, so 12 x 3 = 36 cupcakes.'),
(2, 'logic', 'A car travels 60 km in 1 hour. At that same speed, how far does it travel in 3 hours?', '["120 km", "150 km", "180 km", "200 km"]', 2, 'At 60 km per hour, 3 hours of travel covers 60 x 3 = 180 km.'),
(2, 'logic', 'It takes 3 hours for 2 people to paint a fence, working together at the same rate. How long would it take 1 person alone?', '["1.5 hours", "3 hours", "6 hours", "9 hours"]', 2, '2 people working 3 hours is 6 person-hours of work, so 1 person alone would need 6 hours to do the same job.'),
(2, 'logic', 'A movie starts at 6:45 and lasts 1 hour and 50 minutes. What time does it end?', '["8:15", "8:25", "8:35", "8:45"]', 2, '6:45 plus 1 hour is 7:45, plus another 50 minutes is 8:35.'),
(2, 'logic', 'School begins at 8:15 and the first class lasts 55 minutes. What time does the first class end?', '["9:00", "9:05", "9:10", "9:15"]', 2, '8:15 plus 55 minutes is 9:10.'),
(2, 'logic', 'A tap fills a bucket in 10 minutes. A second, faster tap fills the same bucket in 5 minutes. If both taps run together, do they fill the bucket in less than 5 minutes, exactly 5 minutes, or more than 10 minutes?', '["Less than 5 minutes", "Exactly 5 minutes", "Exactly 7.5 minutes", "More than 10 minutes"]', 0, 'Two taps working together always fill a bucket faster than the faster tap alone, so it takes less than 5 minutes.'),
(2, 'logic', 'Two identical candles are the same height. One burns out in 4 hours, the other burns out in 6 hours. Which candle burns faster?', '["The 4-hour candle", "The 6-hour candle", "They burn at the same rate", "Cannot tell"]', 0, 'Burning out in less time means using up its height more quickly, so the 4-hour candle burns faster.'),
(2, 'logic', 'Three friends - Dev, Ela, and Fay - each own a different pet: a cat, a dog, or a fish. Dev does not own the cat or the fish. Ela does not own the fish. Who owns the fish?', '["Dev", "Ela", "Fay", "Cannot tell"]', 2, 'Dev must own the dog (not cat, not fish). Ela does not own the fish either, so Ela owns the cat, leaving the fish for Fay.'),
(2, 'logic', 'Three siblings - Gio, Hira, and Ivan - are 8, 10, and 12 years old, in some order. Gio is not the youngest. Ivan is not the oldest. Hira is 10. Who is the oldest?', '["Gio", "Hira", "Ivan", "Cannot tell"]', 0, 'Hira is 10, leaving 8 and 12 for Gio and Ivan. Since Ivan is not the oldest, Ivan must be 8 and Gio must be 12, making Gio the oldest.'),
(2, 'logic', 'Four kids - Jai, Kira, Liam, Mona - are ranked 1st through 4th in a contest. Jai is not 1st or 4th. Kira is 1st. Mona is not last. Who is 4th?', '["Jai", "Kira", "Liam", "Mona"]', 2, 'Kira is 1st. Jai cannot be 4th, and Mona cannot be last (4th) either, so the only one left for 4th place is Liam.'),
(2, 'logic', 'Three friends each like a different fruit: apple, banana, or cherry. Nadia does not like banana. Omar does not like apple or banana. What fruit does Omar like?', '["Apple", "Banana", "Cherry", "Cannot tell"]', 2, 'Omar does not like apple or banana, so by elimination Omar likes cherry.'),
(2, 'logic', 'In a class of three students sitting in a row, Priya sits in front of Quincy. Quincy sits in front of Ravi. Who sits at the very back?', '["Priya", "Quincy", "Ravi", "Cannot tell"]', 2, 'The order from front to back is Priya, Quincy, Ravi, so Ravi sits at the very back.'),
(2, 'logic', 'Two boxes, one red and one blue, each hold either marbles or beads, and no box holds both. The red box is not the marbles box. Which box holds the beads?', '["The red box", "The blue box", "Both boxes", "Neither box"]', 0, 'With only two options and the red box ruled out as the marbles box, the red box must hold the beads.'),
(2, 'logic', 'Sara is twice as old as her brother Tom. Tom is 6 years old. How old is Sara?', '["6", "10", "12", "14"]', 2, 'Twice Tom''s age of 6 is 12, so Sara is 12 years old.'),
(2, 'logic', 'In 5 years, Maya will be 15 years old. How old is Maya now?', '["5", "8", "10", "12"]', 2, 'If Maya will be 15 in 5 years, she is 15 - 5 = 10 years old now.'),
(2, 'logic', 'X is Y''s mother. Y is Z''s mother. What is X to Z?', '["Grandmother", "Aunt", "Mother", "Sister"]', 0, 'X is the mother of Y, and Y is the mother of Z, so X is Z''s grandmother.'),
(2, 'logic', 'P is Q''s brother. Q is R''s sister. What is P to R, assuming P, Q, and R are all siblings?', '["Brother", "Father", "Uncle", "Cousin"]', 0, 'If P is Q''s brother and Q is R''s sister, all three share the same parents, making P a brother to R as well.'),
(2, 'logic', 'A jar has 4 green marbles and 6 yellow marbles. If you pick one marble without looking, is it more likely to be green or yellow?', '["Green", "Yellow", "Equally likely", "Cannot tell"]', 1, 'There are more yellow marbles (6) than green ones (4), so picking yellow is more likely.'),
(2, 'logic', 'A spinner is divided into 4 equal sections: red, blue, green, and yellow. What is the chance of landing on blue?', '["1/2", "1/3", "1/4", "1/8"]', 2, 'With 4 equal sections, each one, including blue, has a 1/4 chance of being landed on.'),
(2, 'logic', 'A bag has 10 balls, and all of them are red. If you pick one ball without looking, what is the chance it is red?', '["0%", "50%", "75%", "100%"]', 3, 'Since every ball in the bag is red, picking any ball is guaranteed to be red - a 100% chance.'),
(2, 'logic', 'A coin is flipped once. What are the chances it lands on heads?', '["1/4", "1/3", "1/2", "1"]', 2, 'A fair coin has two equally likely sides, so the chance of heads is 1/2.'),
(2, 'logic', 'Every answer Ben gives is false. Ben says, "It is raining outside." Is it raining outside?', '["Yes", "No", "Cannot tell", "Only in winter"]', 1, 'Since everything Ben says is false, the truth must be the opposite of his statement - it is not raining.'),
(2, 'logic', 'Mia never tells a lie. Mia says, "I am wearing a red shirt." Is Mia wearing a red shirt?', '["Yes", "No", "Cannot tell", "Only sometimes"]', 0, 'Since Mia never lies, her statement must be true - she is wearing a red shirt.'),
(2, 'logic', 'Every statement Zane makes is false. Zane says, "This coin is a quarter." Is the coin a quarter?', '["Yes", "No", "Cannot tell", "Only sometimes"]', 1, 'Since every one of Zane''s statements is false, the coin is not actually a quarter.'),
(2, 'logic', 'Every answer Nina gives is false. Nina says, "I am not hungry." Is Nina hungry?', '["Yes, she is hungry", "No, she is not hungry", "Cannot tell", "Only at lunchtime"]', 0, 'Since Nina''s statement is false, the opposite must be true - "I am not hungry" being false means she is hungry.');
insert into questions (level, category, question_text, options, correct_option_index, explanation) values
(2, 'riddle', 'What can be lit and blown out, and might drip wax tears while it burns?', '["A candle", "A fire", "A match", "A lamp"]', 0, 'A candle is lit, can be blown out, and drips melted wax as it burns.'),
(2, 'riddle', 'What has hands and a face, but no arms, legs, or eyes?', '["A clock", "A doll", "A robot", "A statue"]', 0, 'A clock has an hour hand, a minute hand, and a "face" showing the numbers, but no arms, legs, or eyes.'),
(2, 'riddle', 'What follows you around all day, but disappears completely at night?', '["A shadow", "A friend", "An echo", "A reflection"]', 0, 'Your shadow forms in sunlight and follows your movements, but vanishes once it is dark.'),
(2, 'riddle', 'The more you use me for writing, the shorter I get. What am I?', '["A pencil", "A pen", "A rope", "A ladder"]', 0, 'A pencil wears down and gets shorter each time it is sharpened or used to write.'),
(2, 'riddle', 'What opens up to keep you dry, but is not much use once it turns inside out in the wind?', '["An umbrella", "A raincoat", "A tent", "A hat"]', 0, 'An umbrella opens to block the rain, but a strong gust can flip it inside out, ruining its shape.'),
(2, 'riddle', 'What must be opened before you can walk into a room, even though it is not alive?', '["A door", "A window", "A gate", "A key"]', 0, 'A door swings open to let you into a room, but it has no life of its own.'),
(2, 'riddle', 'What has 365 or 366 pages, one for each day of the year?', '["A dictionary", "A calendar", "A journal", "A textbook"]', 1, 'A calendar is organized with one entry for each day of the year, 365 in a normal year and 366 in a leap year.'),
(2, 'riddle', 'What is round like the Earth, small enough to spin on a stand, and covered in tiny countries?', '["A globe", "A ball", "A map", "A compass"]', 0, 'A globe is a small spinning model of the Earth, showing all of its countries on its round surface.'),
(2, 'riddle', 'What is full of holes, yet is still able to soak up and hold water?', '["A sponge", "A bucket", "A net", "A bottle"]', 0, 'A sponge is riddled with tiny holes but still absorbs and holds a surprising amount of water.'),
(2, 'riddle', 'What can boil water and cook your food, but would hurt you badly if you touched it?', '["Fire", "Ice", "Steam", "Smoke"]', 0, 'Fire produces the heat used for boiling and cooking, but touching it directly causes burns.'),
(2, 'riddle', 'What can freeze a lake solid, yet melts away completely in the summer sun?', '["Ice", "Snow", "Frost", "Fog"]', 0, 'Ice covers a lake in winter but turns back to liquid water once the summer heat arrives.'),
(2, 'riddle', 'What do you leave behind in wet sand, but never actually carry with you?', '["Footprints", "A shadow", "A trail", "A memory"]', 0, 'Footprints are pressed into the sand as you walk, but you never physically carry them away with you.'),
(2, 'riddle', 'What has many rungs to climb, but is not a staircase and cannot move on its own?', '["A ladder", "An escalator", "A rope", "An elevator"]', 0, 'A ladder has a series of rungs to climb, but unlike a staircase it is a separate, portable object.'),
(2, 'riddle', 'What appears in the sky after rain, made of many colors, but can never be touched?', '["A rainbow", "A cloud", "A sunset", "A star"]', 0, 'A rainbow forms from sunlight passing through raindrops, creating colorful bands of light with no physical surface to touch.'),
(2, 'riddle', 'What can be climbed for hours, but never once takes a single step itself?', '["A mountain", "A ladder", "A hill", "A staircase"]', 0, 'A mountain stays perfectly still while climbers make their way up its slopes.'),
(2, 'riddle', 'What stands tall for a hundred years, growing a fresh set of leaves every single spring?', '["A tree", "A mountain", "A statue", "A building"]', 0, 'A tree can live for a very long time, and many kinds regrow their leaves each spring.'),
(2, 'riddle', 'What has many pieces that only make sense once they are all put together?', '["A puzzle", "A song", "A recipe", "A team"]', 0, 'A jigsaw puzzle is made of many small pieces that only form a clear picture once fully assembled.'),
(2, 'riddle', 'What has 26 letters, but is not a word itself?', '["A dictionary", "The alphabet", "A book", "A sentence"]', 1, 'The alphabet is made up of all 26 letters, but it is not a word on its own.'),
(2, 'riddle', 'What can make you cry without ever hurting your feelings?', '["An onion", "Smoke", "Soap", "Pepper spray"]', 0, 'Cutting an onion releases a gas that stings your eyes and makes them water, even though nothing sad has happened.'),
(2, 'riddle', 'What can cover an entire city, yet weighs nothing at all?', '["Fog", "Snow", "Rain", "Dust"]', 0, 'Fog is made of tiny water droplets floating in the air, thick enough to blanket a whole city while weighing nothing itself.'),
(2, 'riddle', 'What can be composed, hummed, and sung, but never held in your hand?', '["A song", "A book", "A painting", "A sculpture"]', 0, 'A song exists as sound and melody, so it can never be physically picked up or held.'),
(2, 'riddle', 'What can never be paused, purchased, or returned once it has passed?', '["Time", "Money", "Love", "Youth"]', 0, 'Time keeps moving forward no matter what, and once a moment has passed, it can never be bought back or replayed.'),
(2, 'riddle', 'What belongs only to you, yet other people say it far more often than you do?', '["Your name", "Your shadow", "Your reflection", "Your voice"]', 0, 'Your name is uniquely yours, but other people call out to you and say your name more often than you say it yourself.'),
(2, 'riddle', 'What grows weaker and weaker the more people find out about it?', '["A secret", "A rumor", "A tree", "A muscle"]', 0, 'A secret loses its power the more people it gets shared with, until it is not really a secret anymore.'),
(2, 'riddle', 'What always ends with a mark that curls like a hook, and is usually answered in words?', '["A statement", "A riddle", "A question", "A command"]', 2, 'A question is written with a question mark at the end and is typically answered with a spoken or written reply.'),
(2, 'riddle', 'What building is packed with countless stories, yet nobody actually lives inside it?', '["A library", "A theater", "A museum", "A school"]', 0, 'A library holds shelves full of stories in the form of books, but it is not a place where people live.'),
(2, 'riddle', 'What lists out ingredients and steps to follow, but cannot cook the meal by itself?', '["A recipe", "A chef", "A menu", "An oven"]', 0, 'A recipe gives instructions for cooking a dish, but it needs a cook to actually follow those steps.'),
(2, 'riddle', 'What always points in the same direction no matter which way you turn it?', '["A compass", "A map", "A clock", "A weathervane"]', 0, 'A compass needle always settles pointing toward magnetic north, regardless of how you spin the compass itself.'),
(2, 'riddle', 'What keeps a ship from drifting out to sea, without ever moving from the ocean floor?', '["An anchor", "A sail", "A rope", "A rudder"]', 0, 'An anchor digs into the seabed and holds a ship in place while staying still itself.'),
(2, 'riddle', 'What can tell you whether it is hot or cold outside, but cannot feel temperature at all?', '["A thermometer", "A blanket", "A fan", "A mirror"]', 0, 'A thermometer measures temperature using liquid or electronics, without actually feeling hot or cold itself.'),
(2, 'riddle', 'What soars high above the ground, held back the whole time by a single string?', '["A kite", "A bird", "A plane", "A balloon"]', 0, 'A kite flies high in the sky but stays tethered to the person flying it by a long string.'),
(2, 'riddle', 'What can stay silent for years, then suddenly wake up and erupt with fire and ash?', '["A volcano", "A bear", "A geyser", "An earthquake"]', 0, 'A dormant volcano can remain quiet for years before suddenly erupting with lava and ash.'),
(2, 'riddle', 'What can you see clearly on a clear night, but never during the daytime, even though it is always there?', '["A star", "The moon", "A cloud", "A firefly"]', 0, 'Stars are always in the sky, but the sun''s brightness hides them from view during the day.'),
(2, 'riddle', 'What does a bird build out of twigs and leaves to keep its eggs safe?', '["A nest", "A burrow", "A hive", "A web"]', 0, 'A bird weaves together twigs and leaves to build a nest that cradles and protects its eggs.'),
(2, 'riddle', 'What is woven without any thread, yet sticky enough to trap unlucky insects?', '["A spider''s web", "A net", "A cocoon", "A trap"]', 0, 'A spider spins a sticky web from silk it produces itself, without using any thread at all.'),
(2, 'riddle', 'What kind of book explains the meaning of every word, including its own name?', '["A dictionary", "An encyclopedia", "A thesaurus", "An atlas"]', 0, 'A dictionary lists definitions for words, and it even includes a definition for the word "dictionary" itself.'),
(2, 'riddle', 'What has a slot for coins, but no way to spend a single one of them itself?', '["A piggy bank", "A vending machine", "A wallet", "A safe"]', 0, 'A piggy bank collects coins through its slot, but it cannot spend any of the money it holds.'),
(2, 'riddle', 'What makes noise to wake you up every morning, without ever needing sleep itself?', '["An alarm clock", "A rooster", "A phone", "A doorbell"]', 0, 'An alarm clock rings at a set time each day and never actually needs to sleep.'),
(2, 'riddle', 'What forms right after it rains, then disappears once the sun dries it up?', '["A puddle", "A river", "A cloud", "A wave"]', 0, 'A puddle forms from rainwater collecting on the ground and evaporates once the sun comes back out.'),
(2, 'riddle', 'What kind of house can be built entirely out of frozen blocks of snow?', '["An igloo", "A castle", "A cabin", "A tent"]', 0, 'An igloo is a dome-shaped shelter built from blocks of packed snow or ice.'),
(2, 'riddle', 'What stands alone in a field day and night, but is not a real person at all?', '["A scarecrow", "A statue", "A mannequin", "A robot"]', 0, 'A scarecrow is dressed like a person and placed in a field to frighten off birds, but it is just stuffed clothing.'),
(2, 'riddle', 'What keeps your place in a story, without ever reading a single word itself?', '["A bookmark", "A pen", "A page", "A library card"]', 0, 'A bookmark simply marks the page you stopped on, without ever reading the book itself.'),
(2, 'riddle', 'What gives a toy its power to move and light up, but eventually runs out of energy?', '["A battery", "A charger", "A switch", "A motor"]', 0, 'A battery stores energy to power a toy, but that energy eventually gets used up.'),
(2, 'riddle', 'What is small enough to hold in the palm of your hand, but can grow into a towering tree?', '["A seed", "A sapling", "A root", "A leaf"]', 0, 'A tiny seed contains everything needed to eventually grow into a full-sized tree.'),
(2, 'riddle', 'What is used to measure how long something is, but never grows in length itself?', '["A ruler", "A scale", "A clock", "A calendar"]', 0, 'A ruler measures the length of other objects, but its own length always stays exactly the same.'),
(2, 'riddle', 'What waits patiently by the side of the road to receive letters, but cannot read a single one?', '["A mailbox", "A postman", "An envelope", "A doorbell"]', 0, 'A mailbox holds incoming mail for the household, but it has no way to actually read what is inside.'),
(2, 'riddle', 'What carries its own home on its back everywhere it goes, and leaves a slimy trail behind it?', '["A snail", "A turtle", "A hermit crab", "A tortoise"]', 0, 'A snail drags its shell-home along with it and leaves behind a trail of slime, unlike a turtle or tortoise.'),
(2, 'riddle', 'What measures the passing of time using falling sand instead of hands or numbers?', '["An hourglass", "A clock", "A calendar", "A sundial"]', 0, 'An hourglass tracks time by letting sand trickle from its top chamber into its bottom chamber.'),
(2, 'riddle', 'What starts out as a hard little kernel, but pops into something fluffy once it is heated?', '["Popcorn", "An egg", "Bread", "Rice"]', 0, 'A popcorn kernel bursts open into a light, fluffy piece of popcorn when heated.'),
(2, 'riddle', 'What gets used twice a day, dipped in paste, but is never actually eaten?', '["A toothbrush", "A spoon", "A napkin", "A fork"]', 0, 'A toothbrush is used with toothpaste each morning and night, but it is a cleaning tool, not food.');
insert into questions (level, category, question_text, options, correct_option_index, explanation) values
(2, 'spatial', 'How many sides does an octagon have?', '["6", "7", "8", "9"]', 2, 'An octagon has 8 sides.'),
(2, 'spatial', 'How many sides does a heptagon have?', '["6", "7", "8", "9"]', 1, 'A heptagon has 7 sides.'),
(2, 'spatial', 'How many sides does a nonagon have?', '["7", "8", "9", "10"]', 2, 'A nonagon has 9 sides.'),
(2, 'spatial', 'How many sides does a decagon have?', '["8", "9", "10", "12"]', 2, 'A decagon has 10 sides.'),
(2, 'spatial', 'How many faces does a triangular pyramid (tetrahedron) have?', '["3", "4", "5", "6"]', 1, 'A triangular pyramid has 4 triangular faces in total, including its base.'),
(2, 'spatial', 'How many vertices does a square-based pyramid have?', '["4", "5", "6", "8"]', 1, 'A square-based pyramid has 4 corners on its square base plus 1 corner at the top, for 5 total.'),
(2, 'spatial', 'How many edges does a square-based pyramid have?', '["4", "6", "8", "10"]', 2, 'A square-based pyramid has 4 edges around its base and 4 edges rising to the top, for 8 total.'),
(2, 'spatial', 'How many faces does a cylinder have?', '["1", "2", "3", "4"]', 2, 'A cylinder has 2 flat circular faces and 1 curved surface, for 3 total.'),
(2, 'spatial', 'How many flat circular faces does a cylinder have?', '["0", "1", "2", "3"]', 2, 'A cylinder has 2 flat circular faces, one on the top and one on the bottom.'),
(2, 'spatial', 'How many faces does a triangular prism have?', '["4", "5", "6", "8"]', 1, 'A triangular prism has 2 triangular faces and 3 rectangular faces, for 5 total.'),
(2, 'spatial', 'How many edges does a triangular prism have?', '["6", "8", "9", "12"]', 2, 'A triangular prism has 9 edges: 3 on the top triangle, 3 on the bottom triangle, and 3 connecting them.'),
(2, 'spatial', 'How many vertices does a triangular prism have?', '["4", "5", "6", "8"]', 2, 'A triangular prism has 6 vertices: 3 on the top triangle and 3 on the bottom triangle.'),
(2, 'spatial', 'What is the sum of all interior angles in any triangle?', '["90 degrees", "180 degrees", "270 degrees", "360 degrees"]', 1, 'The three interior angles of any triangle always add up to 180 degrees.'),
(2, 'spatial', 'What is the sum of all interior angles in any quadrilateral (a 4-sided shape)?', '["180 degrees", "270 degrees", "360 degrees", "450 degrees"]', 2, 'The four interior angles of any quadrilateral always add up to 360 degrees.'),
(2, 'spatial', 'A triangle has exactly one angle of 90 degrees. What kind of triangle is it?', '["Right triangle", "Acute triangle", "Obtuse triangle", "Equilateral triangle"]', 0, 'A triangle with a 90-degree angle is called a right triangle.'),
(2, 'spatial', 'A triangle has one angle greater than 90 degrees. What kind of triangle is it?', '["Right triangle", "Acute triangle", "Obtuse triangle", "Isosceles triangle"]', 2, 'A triangle with an angle greater than 90 degrees is called an obtuse triangle.'),
(2, 'spatial', 'A triangle has all three angles less than 90 degrees. What kind of triangle is it?', '["Right triangle", "Acute triangle", "Obtuse triangle", "Scalene triangle"]', 1, 'A triangle where every angle is less than 90 degrees is called an acute triangle.'),
(2, 'spatial', 'A triangle has two sides that are exactly the same length. What is this type of triangle called?', '["Scalene", "Isosceles", "Equilateral", "Right"]', 1, 'A triangle with exactly two equal sides is called an isosceles triangle.'),
(2, 'spatial', 'A triangle has three sides that are all different lengths. What is this type of triangle called?', '["Scalene", "Isosceles", "Equilateral", "Obtuse"]', 0, 'A triangle with no equal sides at all is called a scalene triangle.'),
(2, 'spatial', 'How many lines of symmetry does a regular hexagon have?', '["3", "4", "6", "8"]', 2, 'A regular hexagon has 6 lines of symmetry.'),
(2, 'spatial', 'How many lines of symmetry does an equilateral triangle have?', '["1", "2", "3", "4"]', 2, 'An equilateral triangle has 3 lines of symmetry, one through each vertex and the midpoint of the opposite side.'),
(2, 'spatial', 'How many lines of symmetry does a rectangle that is not a square have?', '["0", "1", "2", "4"]', 2, 'A non-square rectangle has 2 lines of symmetry, one horizontal and one vertical.'),
(2, 'spatial', 'How many lines of symmetry does the capital letter A have?', '["0", "1", "2", "4"]', 1, 'The capital letter A has 1 vertical line of symmetry down its middle.'),
(2, 'spatial', 'How many lines of symmetry does the capital letter H have?', '["0", "1", "2", "3"]', 2, 'The capital letter H has 2 lines of symmetry: one vertical and one horizontal.'),
(2, 'spatial', 'How many lines of symmetry does the capital letter S have?', '["0", "1", "2", "4"]', 0, 'The capital letter S has 0 lines of symmetry - it can be rotated to match itself, but no mirror line works.'),
(2, 'spatial', 'If you are facing South and turn 90 degrees clockwise, which direction do you face?', '["North", "East", "South", "West"]', 3, 'Going clockwise from South by 90 degrees points you to West.'),
(2, 'spatial', 'If you are facing West and turn 90 degrees counterclockwise, which direction do you face?', '["North", "South", "East", "West"]', 1, 'Going counterclockwise from West by 90 degrees points you to South.'),
(2, 'spatial', 'If you are facing North and turn 270 degrees clockwise, which direction do you face?', '["East", "South", "West", "North"]', 2, 'Turning 270 degrees clockwise from North (through East, then South) ends up facing West.'),
(2, 'spatial', 'If you are facing East and turn 90 degrees clockwise twice in a row, which direction do you face?', '["North", "South", "West", "East"]', 2, 'Turning 90 degrees clockwise from East faces South, and turning another 90 degrees clockwise from South faces West.'),
(2, 'spatial', 'A rectangle is twice as long as it is wide. If its width is 5 cm, what is its length?', '["5 cm", "7 cm", "10 cm", "15 cm"]', 2, 'Twice the width of 5 cm is 10 cm, so the length is 10 cm.'),
(2, 'spatial', 'A square has a side length of 6 cm. What is its perimeter?', '["12 cm", "18 cm", "24 cm", "36 cm"]', 2, 'A square''s perimeter is 4 times its side length: 4 x 6 = 24 cm.'),
(2, 'spatial', 'A rectangle is 8 cm long and 3 cm wide. What is its perimeter?', '["11 cm", "16 cm", "22 cm", "24 cm"]', 2, 'Perimeter = 2 x (length + width) = 2 x (8 + 3) = 22 cm.'),
(2, 'spatial', 'Which shape has the most sides: a pentagon, a hexagon, or an octagon?', '["A pentagon", "A hexagon", "An octagon", "They are equal"]', 2, 'A pentagon has 5 sides, a hexagon has 6, and an octagon has 8 - the octagon has the most.'),
(2, 'spatial', 'Which 3D shape looks exactly the same from every direction, like a ball?', '["A cube", "A sphere", "A cone", "A cylinder"]', 1, 'A sphere is perfectly round in every direction, so it looks identical no matter which way you view it.'),
(2, 'spatial', 'Which 3D shape has exactly one curved surface and two flat circular ends?', '["A cone", "A cylinder", "A sphere", "A cube"]', 1, 'A cylinder has two flat circular ends connected by one curved surface.'),
(2, 'spatial', 'How many of a cube''s faces are square in shape?', '["0", "2", "4", "6"]', 3, 'Every one of a cube''s 6 faces is a square.'),
(2, 'spatial', 'If you unfold a cube completely flat, how many square faces does the resulting net have?', '["4", "5", "6", "8"]', 2, 'A cube''s net always has all 6 of its square faces laid out flat.'),
(2, 'spatial', 'Which shape can tile a floor with no gaps between pieces by itself: a circle or a hexagon?', '["A circle", "A hexagon", "Neither", "Both equally well"]', 1, 'Hexagons fit together perfectly with no gaps, while circles always leave curved gaps between them.'),
(2, 'spatial', 'What do you call a shape whose sides and angles are all equal?', '["An irregular polygon", "A regular polygon", "A concave polygon", "A prism"]', 1, 'A shape with all equal sides and all equal angles is called a regular polygon.'),
(2, 'spatial', 'What is it called when a shape is flipped over like a mirror image?', '["A rotation", "A reflection", "A translation", "A dilation"]', 1, 'Flipping a shape to create its mirror image is called a reflection.'),
(2, 'spatial', 'What is it called when a shape slides to a new position without turning or flipping?', '["A rotation", "A reflection", "A translation", "A dilation"]', 2, 'Sliding a shape to a new spot without rotating or flipping it is called a translation.'),
(2, 'spatial', 'What is it called when a shape is turned around a fixed point?', '["A rotation", "A reflection", "A translation", "A dilation"]', 0, 'Turning a shape around a fixed point is called a rotation.'),
(2, 'spatial', 'What is it called when a shape is made larger or smaller while keeping the same proportions?', '["A rotation", "A reflection", "A dilation", "A translation"]', 2, 'Resizing a shape while keeping its proportions the same is called a dilation.'),
(2, 'spatial', 'A square is rotated 45 degrees so it balances on one corner. What does it now look like?', '["A diamond", "A triangle", "A pentagon", "A rectangle"]', 0, 'A square balanced on one corner is commonly described as looking like a diamond shape.'),
(2, 'spatial', 'How many right angles does a square have?', '["2", "3", "4", "8"]', 2, 'All four corners of a square are right angles.'),
(2, 'spatial', 'How many obtuse angles can a right triangle have?', '["0", "1", "2", "3"]', 0, 'A right triangle already has one 90-degree angle, and its other two angles must add up to 90 degrees, so neither can be obtuse.'),
(2, 'spatial', 'Two shapes are congruent. What does that mean?', '["They are the same color", "They are exactly the same size and shape", "They have the same number of sides only", "They are similar but different sizes"]', 1, 'Congruent shapes are identical in both size and shape.'),
(2, 'spatial', 'Two shapes are similar in the math sense, but not congruent. What does that mean?', '["Same shape, different size", "Same size, different shape", "Identical in every way", "Completely unrelated shapes"]', 0, 'Similar shapes have the same shape and proportions but can be different sizes.'),
(2, 'spatial', 'A map uses a scale of 1 cm = 10 km. If two cities are 5 cm apart on the map, how far apart are they in real life?', '["5 km", "15 km", "50 km", "100 km"]', 2, 'At a scale of 1 cm = 10 km, 5 cm on the map represents 5 x 10 = 50 km in real life.'),
(2, 'spatial', 'If North is at the top of a map, which general direction do you travel going from the top-left corner to the bottom-right corner?', '["Northeast", "Northwest", "Southeast", "Southwest"]', 2, 'Moving from top-left to bottom-right means heading both East and South at once, which is the Southeast direction.');
insert into questions (level, category, question_text, options, correct_option_index, explanation) values
(3, 'logic', 'Five friends shake hands with each other exactly once each. How many total handshakes happen?', '["8","10","12","15"]', 1, 'Each of the 5 friends shakes hands with 4 others, but that counts each handshake twice: (5 x 4) / 2 = 10.'),
(3, 'logic', 'A is taller than B. D is shorter than B. C is shorter than D. Who is the tallest of the four?', '["A","B","C","D"]', 0, 'Putting the clues together: A is tallest, then B, then D, then C - so A is the tallest.'),
(3, 'logic', 'Pipe A can fill a tank in 6 hours alone. Pipe B can fill the same tank in 3 hours alone. If both pipes run together, how long will it take to fill the tank?', '["1.5 hours","2 hours","3 hours","4.5 hours"]', 1, 'Pipe A fills 1/6 of the tank per hour and Pipe B fills 1/3 per hour. Together: 1/6 + 1/3 = 1/2 per hour, so it takes 2 hours.'),
(3, 'logic', 'A 250-page book is read at a steady 25 pages a day, starting on Day 1. On which day will it be finished?', '["Day 8","Day 9","Day 10","Day 11"]', 2, '250 pages divided by 25 pages a day is 10 days, so the book is finished on Day 10.'),
(3, 'logic', 'Three siblings split $60 in the ratio 2:3:5. How much does the sibling with the largest share receive?', '["$20","$24","$30","$36"]', 2, 'The ratio has 10 total parts, so each part is worth $6. The largest share is 5 parts: 5 x $6 = $30.'),
(3, 'logic', 'A works twice as fast as B. Working together, they finish a job in 4 days. How many days would B alone need to finish the same job?', '["6 days","8 days","12 days","16 days"]', 2, 'If B''s rate is x jobs/day, A''s rate is 2x. Together they do 3x jobs/day, and 3x x 4 days = 1 job, so x = 1/12. B alone takes 12 days.'),
(3, 'logic', 'Find the next number in this sequence, where each term is the sum of the two terms before it: 3, 5, 8, 13, 21, ___?', '["29","31","34","36"]', 2, 'This is a Fibonacci-style sequence: each term is the sum of the two before it. 13 + 21 = 34.'),
(3, 'logic', 'A survey of 50 students found that 28 like cricket, 22 like football, and 10 like both sports. How many students like neither sport?', '["6","8","10","12"]', 2, 'At least one sport: 28 + 22 - 10 = 40 (subtracting the 10 counted twice). Neither: 50 - 40 = 10.'),
(3, 'logic', 'Rahul is 4 years older than his brother Kunal. In 6 years, the sum of their ages will be 40. How old is Kunal right now?', '["10","12","14","16"]', 1, 'Let Kunal be k now, so Rahul is k+4. In 6 years: (k+6) + (k+10) = 40, so 2k + 16 = 40, giving k = 12.'),
(3, 'logic', 'In a class of 30 students, every student plays exactly one of chess or checkers. 18 students play chess. How many play checkers?', '["10","12","14","18"]', 1, 'Since every student plays exactly one of the two games, checkers players = 30 - 18 = 12.'),
(3, 'logic', 'A train travels 60 km in 45 minutes at a steady speed. At that same speed, how long will it take to travel 100 km?', '["60 minutes","75 minutes","80 minutes","90 minutes"]', 1, 'The speed is 60 km / 0.75 hours = 80 km/h. Time for 100 km: 100 / 80 = 1.25 hours, which is 75 minutes.'),
(3, 'logic', 'Meena has twice as many marbles as Farah. Together they have 36 marbles. How many marbles does Meena have?', '["12","18","24","30"]', 2, 'If Farah has f marbles, Meena has 2f, and f + 2f = 36, so f = 12. Meena has 2 x 12 = 24.'),
(3, 'logic', 'A farmer has only chickens and cows in a field. Together they have 20 heads and 56 legs. How many chickens are there?', '["8","10","12","14"]', 2, 'Every animal has 1 head, so chickens + cows = 20. Chickens have 2 legs and cows have 4: 2(chickens) + 4(cows) = 56. Solving both equations gives 12 chickens and 8 cows.'),
(3, 'logic', 'If 3 machines can each make 1 toy in 3 minutes, working in parallel, how many minutes would it take 100 such machines to make 100 toys?', '["3 minutes","33 minutes","100 minutes","300 minutes"]', 0, 'Each machine independently makes its own toy in 3 minutes, so however many machines you have working at once, it still only takes 3 minutes for each to finish one toy.'),
(3, 'logic', 'Two trains start 300 km apart and move toward each other, one at 50 km/h and the other at 70 km/h. How long until they meet?', '["2 hours","2.5 hours","3 hours","3.5 hours"]', 1, 'Together they close the gap at 50 + 70 = 120 km/h. Time to meet: 300 / 120 = 2.5 hours.'),
(3, 'logic', 'In a row of children, Neha is 7th from the left end and 12th from the right end. How many children are in the row in total?', '["17","18","19","20"]', 1, 'Adding her position from each end double-counts Neha herself: 7 + 12 - 1 = 18 children in total.'),
(3, 'logic', 'All squares are rectangles. All rectangles are quadrilaterals. Is every square definitely a quadrilateral?', '["Yes, definitely","No","Only sometimes","Cannot be determined"]', 0, 'Since every square is a rectangle, and every rectangle is a quadrilateral, every square must also be a quadrilateral.'),
(3, 'logic', 'No fish are mammals. All whales are mammals. Can a whale possibly be a fish?', '["Yes, always","No, never","Only sometimes","Cannot be determined"]', 1, 'Whales are mammals, and no mammal can be a fish (since no fish are mammals), so a whale can never be a fish.'),
(3, 'logic', 'A is twice as old as B was 5 years ago. If B is 15 years old now, how old is A now?', '["18","20","22","25"]', 1, 'Five years ago, B was 15 - 5 = 10. A is twice that age: 2 x 10 = 20.'),
(3, 'logic', 'A bookstore has fiction and non-fiction books in the ratio 5:3. If there are 240 books in total, how many are non-fiction?', '["75","90","105","120"]', 1, 'The ratio has 8 total parts, so each part is 240 / 8 = 30 books. Non-fiction is 3 parts: 3 x 30 = 90.'),
(3, 'logic', 'Four runners - Kiran, Leo, Maya, and Nora - finish a race with no ties. Nora finishes last. Leo finishes right before Kiran. Maya finishes before Leo. Who finishes first?', '["Kiran","Leo","Maya","Nora"]', 2, 'Nora is 4th. Maya finishes before Leo, and Leo finishes right before Kiran, so the order among the other three must be Maya, then Leo, then Kiran - Maya finishes first.'),
(3, 'logic', 'A shopkeeper marks up an item''s cost price by 25% to set the selling price. If the selling price is $100, what was the original cost price?', '["$75","$80","$85","$90"]', 1, 'If the cost price is C, then C x 1.25 = 100, so C = 100 / 1.25 = $80.'),
(3, 'logic', 'In a music group, everyone who plays guitar also plays piano. Ten people play piano, and 4 of them do not play guitar. How many people play guitar?', '["4","6","8","10"]', 1, 'Since guitar players are a subset of piano players, guitar players = 10 total piano players - 4 who only play piano = 6.'),
(3, 'logic', 'A tank is 1/3 full. After adding 20 liters, it becomes 3/5 full. What is the tank''s total capacity?', '["60 liters","75 liters","90 liters","100 liters"]', 1, 'The 20 liters filled the gap between 1/3 and 3/5 of the tank, which is 3/5 - 1/3 = 4/15 of the capacity. So the capacity is 20 / (4/15) = 75 liters.'),
(3, 'logic', 'In a certain code, each letter is shifted forward by 1 in the alphabet (so COLD becomes DPME). Using the same code, how is WARM written?', '["XBSN","XBSM","YBSN","XCSN"]', 0, 'Shifting each letter of WARM forward by 1: W to X, A to B, R to S, M to N, giving XBSN.'),
(3, 'logic', 'A is the mother of B. B is the sister of C. What is A to C?', '["Mother","Aunt","Grandmother","Sister"]', 0, 'Since B and C are siblings who share the same mother, A (B''s mother) is also C''s mother.'),
(3, 'logic', 'In a race of 8 runners, how many different ways can the gold, silver, and bronze medals be awarded, if every runner could win any medal and order matters?', '["56","168","336","512"]', 2, 'This is a permutation of 8 runners taken 3 at a time: 8 x 7 x 6 = 336.'),
(3, 'logic', 'A number increased by 20% gives 60. What was the original number?', '["40","45","50","55"]', 2, 'If the original number is x, then x x 1.2 = 60, so x = 60 / 1.2 = 50.'),
(3, 'logic', 'Three consecutive even numbers add up to 84. What is the largest of the three numbers?', '["26","28","30","32"]', 2, 'Let the numbers be n, n+2, n+4. Their sum is 3n + 6 = 84, so n = 26. The largest is n + 4 = 30.'),
(3, 'logic', 'If it takes 4 painters 8 hours to paint a house, how many hours would it take 8 painters to paint the same house, working at the same rate?', '["2 hours","4 hours","6 hours","16 hours"]', 1, 'The total work is 4 x 8 = 32 painter-hours. With 8 painters sharing that work: 32 / 8 = 4 hours.'),
(3, 'logic', 'A jar has only nickels and dimes. There are 40 coins in total, and there are 20 fewer dimes than nickels. How many nickels are there?', '["10","20","30","40"]', 2, 'Let nickels = n and dimes = d. n + d = 40 and n - d = 20. Adding these equations: 2n = 60, so n = 30.'),
(3, 'logic', 'Point A is directly south of point B. Point D is directly west of point A. Which direction is point D from point B?', '["Northwest","Southwest","Southeast","Northeast"]', 1, 'D is south of B (because it shares A''s position south of B) and also west of A, which is already south of B - so D ends up southwest of B.'),
(3, 'logic', 'Six people are seated around a circular table. If each person shakes hands only with the two people sitting directly next to them, how many total handshakes occur?', '["5","6","10","12"]', 1, 'Each of the 6 people shakes 2 hands, giving 12 handshake-ends, but each handshake has two ends, so there are 12 / 2 = 6 actual handshakes.'),
(3, 'logic', 'The sum of two numbers is 45, and their difference is 9. What is the larger number?', '["24","27","30","33"]', 1, 'Adding the two equations x + y = 45 and x - y = 9 gives 2x = 54, so x = 27.'),
(3, 'logic', 'Four people are in an age chain: A is older than B, B is older than C, and C is older than D. D is 10 years old, and each person is exactly 3 years older than the next. How old is A?', '["16","17","19","21"]', 2, 'D = 10, C = 13, B = 16, A = 19, since each is 3 years older than the one before.'),
(3, 'logic', 'In a group of 40 people, 25 speak English, 15 speak French, and 5 speak both languages. How many people speak neither language?', '["3","5","7","10"]', 1, 'At least one language: 25 + 15 - 5 = 35. Neither: 40 - 35 = 5.'),
(3, 'logic', 'A two-digit number has digits that add up to 9. The tens digit is twice the units digit. What is the number?', '["36","45","63","72"]', 2, 'If the units digit is u, the tens digit is 2u, and 2u + u = 9, so u = 3 and the tens digit is 6. The number is 63.'),
(3, 'logic', 'Priya can paint a fence alone in 4 hours. Working together with her friend Jai, they finish the same fence in 2.4 hours. How long would Jai take to paint it alone?', '["5 hours","6 hours","7 hours","8 hours"]', 1, 'Priya''s rate is 1/4 fence per hour. Combined rate is 1/2.4 = 5/12 per hour. Jai''s rate is 5/12 - 3/12 = 2/12 = 1/6, so Jai alone takes 6 hours.'),
(3, 'logic', 'In a code, each letter is shifted 5 places earlier in the alphabet (so F becomes A). Using this code, what does the word KNOWS become?', '["FIJRN","FIJRO","EIJRN","FHJRN"]', 0, 'Shifting each letter of KNOWS back by 5: K to F, N to I, O to J, W to R, S to N, giving FIJRN.'),
(3, 'logic', 'Of 60 apples, one third are rotten and thrown away. Of the remaining good apples, half are given away. How many good apples are left?', '["10","15","20","25"]', 2, 'One third of 60 is 20 rotten apples, leaving 40 good ones. Half of those 40 are given away, leaving 20.'),
(3, 'logic', 'A is B''s brother. C is B''s mother. D is C''s husband. What is D to A?', '["Father","Uncle","Grandfather","Brother"]', 0, 'C is B''s mother and D is her husband, making D a parent in the family. Since A is B''s sibling, A is also C and D''s child, so D is A''s father.'),
(3, 'logic', 'A bag has red, blue, and green marbles in the ratio 3:4:5. If there are 15 red marbles, how many green marbles are there?', '["15","20","25","30"]', 2, 'Since 3 parts corresponds to 15 red marbles, each part is 5 marbles. Green is 5 parts: 5 x 5 = 25.'),
(3, 'logic', 'Sara''s mother is the only daughter of Tom''s mother. What is the relationship between Tom and Sara?', '["Uncle","Father","Cousin","Grandfather"]', 0, 'Tom''s mother''s only daughter must be Tom''s sister (assuming Tom is her son), and that daughter is Sara''s mother - so Tom is Sara''s uncle.'),
(3, 'logic', 'A number is divisible by both 4 and 6. Which of the following must it also be divisible by?', '["8","9","10","12"]', 3, 'The smallest number divisible by both 4 and 6 is their least common multiple, 12, so any such number must also be divisible by 12.'),
(3, 'logic', 'In a family there are two fathers and two sons, but only three people in total. How is this possible?', '["A grandfather, a father, and a son","Twins and their father","Two unrelated families","It is not possible"]', 0, 'A grandfather, his son (who is also a father), and his grandson together form exactly two father-son relationships among only three people.'),
(3, 'logic', 'A weighs twice as much as B, and B weighs 3 kg more than C. If C weighs 9 kg, how much does A weigh?', '["18 kg","21 kg","24 kg","27 kg"]', 2, 'C weighs 9 kg, so B weighs 9 + 3 = 12 kg, and A weighs twice that: 2 x 12 = 24 kg.'),
(3, 'logic', 'Six identical books, each 4 cm thick, are stacked together. If 2 books are removed from the stack, how tall is the remaining stack?', '["12 cm","16 cm","20 cm","24 cm"]', 1, 'The remaining stack has 6 - 2 = 4 books, each 4 cm thick: 4 x 4 = 16 cm.'),
(3, 'logic', 'A always tells the truth. A says, I am not a liar. What can we conclude?', '["The statement is true, which fits A being a truth-teller","The statement is a paradox","A must actually be a liar","Cannot be determined"]', 0, 'Since we are told A always tells the truth, the statement I am not a liar is simply true - there is no contradiction here.'),
(3, 'logic', 'There are 100 students, and every student plays at least one of basketball or volleyball. 60 play basketball and 50 play volleyball. How many students play both sports?', '["5","10","15","20"]', 1, 'Since everyone plays at least one sport, 60 + 50 - both = 100, so both = 110 - 100 = 10.'),
(3, 'logic', 'A is the only child of B. C is B''s mother. What is C to A?', '["Grandmother","Aunt","Mother","Sister"]', 0, 'C is B''s mother, and B is A''s parent, which makes C the grandmother of A.');
insert into questions (level, category, question_text, options, correct_option_index, explanation) values
(3, 'riddle', 'The more I am used, the shorter I become, yet you miss me most when the room goes dark. What am I?', '["A candle","A pencil","A battery","A match"]', 0, 'A candle grows shorter the more it burns, and its light is what you miss most once the room goes dark.'),
(3, 'riddle', 'I have no mouth yet I can tick all day long, and my two hands never hold a single thing. What am I?', '["A glove","A clock","A statue","A robot"]', 1, 'A clock has hands that tick around its face all day, but they are only pointers, never actually holding anything.'),
(3, 'riddle', 'I show you mountains and rivers with no water or stone, and whole countries with not a single person inside them. What am I?', '["A globe","A photograph","A map","A painting"]', 2, 'A map represents real mountains, rivers, and countries using only lines and symbols on paper, with none of the real thing inside it.'),
(3, 'riddle', 'I follow you all day long, vanish completely at night, and grow tallest exactly when the sun is low. What am I?', '["A shadow","A reflection","A ghost","A silhouette"]', 0, 'A shadow follows you whenever there is light, disappears in the dark, and stretches longest when the sun is near the horizon.'),
(3, 'riddle', 'I answer back the moment you call out, repeating your very own words, yet I am not a person at all. What am I?', '["A parrot","An echo","A recording","A reflection"]', 1, 'An echo repeats the sound of your voice back to you, bouncing off a distant surface, with no person actually speaking.'),
(3, 'riddle', 'I have ribs but no body at all, and I am happiest exactly when the sky begins to cry. What am I?', '["An umbrella","A skeleton","A tent","A kite"]', 0, 'An umbrella has rib-like spokes holding up its fabric, and it gets used most whenever it starts raining.'),
(3, 'riddle', 'I have 88 keys of my own, yet I cannot open a single lock. What am I?', '["A typewriter","A piano","A safe","A keyring"]', 1, 'A standard piano has 88 keys, but they are for playing music, not for opening any locks.'),
(3, 'riddle', 'I have twelve members but I only exist for a single year before starting over again. What am I?', '["A calendar","A committee","A council","A choir"]', 0, 'A calendar is made up of twelve months, and a brand new one begins again with every new year.'),
(3, 'riddle', 'I carry your words inside me without saying a single one myself, and I am often licked before I set off on a journey. What am I?', '["A letter","An envelope","A stamp","A postcard"]', 1, 'An envelope holds a written message inside without speaking itself, and its flap is often licked shut before being mailed.'),
(3, 'riddle', 'I have a mouth and a bed of my own, yet I never once sleep or eat anything. What am I?', '["A river","A volcano","A cave","A valley"]', 0, 'A river has a mouth (where it meets the sea) and a bed (its bottom channel), but it never actually sleeps or eats.'),
(3, 'riddle', 'I stand tall without any legs at all, and I wear snow like a hat, yet I never feel the cold. What am I?', '["A mountain","A statue","A flagpole","A lighthouse"]', 0, 'A mountain stands tall with no legs, is often capped with snow at its peak, but has no body to actually feel cold.'),
(3, 'riddle', 'I have an eye of my own, but I cannot see with it, and I pull a thread along wherever I travel. What am I?', '["A needle","A hook","A spool","A loom"]', 0, 'A sewing needle has an eye (the small hole), but it is only for threading, not for seeing anything.'),
(3, 'riddle', 'I have a tongue but I have never tasted a single thing, and I only speak when someone strikes me. What am I?', '["A drum","A bell","A gong","A cymbal"]', 1, 'A bell has a tongue-shaped clapper inside it, and it only makes a sound (speaks) when it is struck.'),
(3, 'riddle', 'I have five fingers of my own but not a single bone, and I only come alive once I am on someone''s hand. What am I?', '["A puppet","A glove","A mitten","A handprint"]', 1, 'A glove has five finger-shaped sections but no bones inside, and it only takes shape once a real hand slips inside it.'),
(3, 'riddle', 'I shine brightly at night but vanish completely by day, and people often make wishes upon me. What am I?', '["The moon","A star","A firefly","A candle flame"]', 1, 'A star is visible shining at night but fades from view in daylight, and people traditionally wish upon one.'),
(3, 'riddle', 'I can make you cry without ever hurting you, and I am made of many thin layers wrapped around each other. What am I?', '["A book","An onion","A rose","A cabbage"]', 1, 'Cutting an onion releases a gas that makes your eyes water, even though it never actually hurts you, and it is made of many thin layers.'),
(3, 'riddle', 'I have many pages of my own, but I am not a tree, and I can carry you to faraway places without you ever moving. What am I?', '["A map","A book","A ticket","A letter"]', 1, 'A book is made of pages and can transport your imagination to faraway places, all while you stay perfectly still.'),
(3, 'riddle', 'I show you your own face clearly, yet I have no eyes of my own, and I always flip your left and right sides around. What am I?', '["A mirror","A camera","A window","A photograph"]', 0, 'A mirror reflects your face back at you without having any eyes itself, and it reverses left and right in the reflection.'),
(3, 'riddle', 'I help you travel upward and downward, but I never take a single step or move on my own. What am I?', '["An escalator","A ladder","An elevator","A staircase"]', 1, 'A ladder lets you climb up or down, but it stays completely still itself while you do all the moving.'),
(3, 'riddle', 'I grow bigger the more air I am given, and yet one small pin can bring my whole existence to an end. What am I?', '["A tire","A balloon","A bubble","A parachute"]', 1, 'A balloon expands as more air fills it, but a single sharp pin is enough to pop it instantly.'),
(3, 'riddle', 'I travel all around the world with you, yet I always come back empty of any memories, only full of clothes. What am I?', '["A suitcase","A camera","A diary","A postcard"]', 0, 'A suitcase goes wherever you travel, packed with clothes, but it holds no memories of the trip itself.'),
(3, 'riddle', 'I wear a carrot for a nose and two pieces of coal for eyes, but I vanish completely once the sun gets too friendly. What am I?', '["A puppet","A snowman","A statue","A doll"]', 1, 'A snowman is traditionally built with a carrot nose and coal eyes, and it melts away once the sun warms it up.'),
(3, 'riddle', 'I dance across the sky on the end of a single string, but without any wind at all, I cannot fly. What am I?', '["A kite","A balloon","A flag","A paper plane"]', 0, 'A kite is flown on a string and needs wind to lift it and keep it dancing in the sky.'),
(3, 'riddle', 'I can tell you whether something is hot or cold, but I have never once felt either myself. What am I?', '["A thermometer","A blanket","A fan","A heater"]', 0, 'A thermometer measures temperature accurately, but being just an instrument, it never actually feels hot or cold.'),
(3, 'riddle', 'I am made of many small pieces, but I only make real sense once every single piece is put together. What am I?', '["A jigsaw puzzle","A mosaic","A quilt","A collage"]', 0, 'A jigsaw puzzle is made of many individual pieces that only form a complete picture once they are all correctly assembled.'),
(3, 'riddle', 'No matter which way you turn me, I always end up pointing in the very same direction. What am I?', '["A weathervane","A compass","A clock hand","A signpost"]', 1, 'A compass needle always settles to point toward magnetic north, no matter which direction you turn the compass itself.'),
(3, 'riddle', 'I appear in the sky right after the rain, painted with many colors, but you can never actually touch me. What am I?', '["A rainbow","A cloud","A sunset","A kite"]', 0, 'A rainbow appears in the sky after rain, displaying many colors, but it is just light and can never be physically touched.'),
(3, 'riddle', 'I hold thousands of stories inside me, yet I have never spoken a single word out loud myself, and you must stay quiet inside me. What am I?', '["A bookstore","A library","A theater","A museum"]', 1, 'A library holds thousands of stories on its shelves, stays silent itself, and requires visitors to stay quiet too.'),
(3, 'riddle', 'No two people in the entire world share the exact same one of me, and I am found right at the tip of your finger. What am I?', '["A fingerprint","A hand","A signature","A knuckle"]', 0, 'Every person''s fingerprint is completely unique, and it sits right at the tip of each finger.'),
(3, 'riddle', 'I am covered in numbers but I am not a clock, and I help you measure things along a perfectly straight line. What am I?', '["A ruler","A scale","A compass","A protractor"]', 0, 'A ruler is marked with numbered measurements and is used to measure length along a straight edge.'),
(3, 'riddle', 'I sleep quietly for years at a time, but when I finally wake up, I can spit fire from deep inside the earth. What am I?', '["An earthquake","A volcano","A geyser","A canyon"]', 1, 'A volcano can lie dormant (sleeping) for years before erupting, sending fire and lava up from deep underground.'),
(3, 'riddle', 'I am a net with no fisherman at all, built without any hands, and I trap things without ever meaning to cause harm. What am I?', '["A spider web","A fishing net","A birdcage","A trap"]', 0, 'A spider web is a net-like structure spun without hands or a fisherman, catching insects simply as part of how it works.'),
(3, 'riddle', 'I am heavy and made of metal, and my entire job is to keep a ship from drifting away. What am I?', '["A chain","An anchor","A dock","A rope"]', 1, 'An anchor is a heavy metal object whose only job is to hold a ship firmly in place so it cannot drift.'),
(3, 'riddle', 'Someone else controls my every move with strings attached to me, yet to onlookers I appear to dance all on my own. What am I?', '["A puppet","A robot","A kite","A marionette doll"]', 0, 'A puppet is moved by someone pulling strings from above, even though it looks to an audience like it is dancing by itself.'),
(3, 'riddle', 'I am small and sticky on one side, and I must be licked before I can send a letter on its journey. What am I?', '["An envelope","A postage stamp","A sticker","A label"]', 1, 'A postage stamp is small and sticky on the back, and it is licked (or wetted) and stuck on before a letter can be mailed.'),
(3, 'riddle', 'I contain every single word you will ever need, but I have no story of my own to tell. What am I?', '["An encyclopedia","A dictionary","A thesaurus","A textbook"]', 1, 'A dictionary lists the meanings of every word in a language, but unlike a novel, it tells no story of its own.'),
(3, 'riddle', 'I am full of coins but I cannot walk anywhere, and you must break me open just to see what is inside. What am I?', '["A vault","A piggy bank","A treasure chest","A wallet"]', 1, 'A piggy bank holds coins saved up over time, cannot move on its own, and is often broken open to reach the savings inside.'),
(3, 'riddle', 'I have several bars of my own but I am not a prison, and I make music whenever you strike me with a mallet. What am I?', '["A xylophone","A drum","A harp","A cello"]', 0, 'A xylophone is made of a row of bars that produce musical notes when struck with a mallet, unlike prison bars.'),
(3, 'riddle', 'I have 64 squares of my own but I am not a house, and kings and queens do battle across my surface. What am I?', '["A chessboard","A checkerboard","A puzzle mat","A game table"]', 0, 'A chessboard has 64 squares, and it is exactly where chess pieces like kings and queens face off against each other.'),
(3, 'riddle', 'I tell you exactly what to do, step by step, yet I have never once cooked a single meal myself. What am I?', '["A cookbook","A recipe","A chef","An oven"]', 1, 'A recipe gives precise step-by-step instructions for cooking, but being only words on a page, it never cooks anything itself.'),
(3, 'riddle', 'I must be kept a closely guarded secret, but I am not a person, and I can open doors that no ordinary key ever could. What am I?', '["A password","A key","A code","A combination lock"]', 0, 'A password must be kept secret like a person''s trust, yet it can unlock digital doors that a physical key never could.'),
(3, 'riddle', 'I am small and quiet, buried deep in the dark soil, but given enough time and water, I grow into something tall. What am I?', '["A bulb","A seed","A root","A sprout"]', 1, 'A seed starts out tiny and buried underground, but with time, water, and sunlight, it can grow into a tall plant.'),
(3, 'riddle', 'I make faraway things look close enough to touch, yet I myself have never moved a single inch. What am I?', '["A telescope","Binoculars","A camera lens","A microscope"]', 0, 'A telescope magnifies distant objects so they appear close, even though the telescope itself stays perfectly still.'),
(3, 'riddle', 'I show only three colors, yet I have never painted a single thing, and drivers obey me without ever questioning why. What am I?', '["A rainbow","A traffic light","A flag","A road sign"]', 1, 'A traffic light cycles through red, yellow, and green, and drivers follow its signals automatically, even though it never paints anything.'),
(3, 'riddle', 'I have strings of my own but I am not a puppet, and you must pluck me carefully to hear my true voice. What am I?', '["A guitar","A puppet","A kite","A bow"]', 0, 'A guitar has strings that are plucked or strummed to produce its musical sound, unlike a puppet''s strings.'),
(3, 'riddle', 'I carry my own house wherever I go, and I never once have to pay any rent for it. What am I?', '["A turtle","A snail","A hermit crab","A tortoise"]', 1, 'A snail carries its shell (its house) on its back everywhere it travels, with no rent ever required.'),
(3, 'riddle', 'I am a house built entirely from frozen blocks, yet I somehow keep you warmer inside than you might expect. What am I?', '["A cabin","An igloo","A tent","A greenhouse"]', 1, 'An igloo is built from blocks of packed snow and ice, but the trapped air inside actually helps keep it surprisingly warm.'),
(3, 'riddle', 'I am one of many identical twins packed together in a box, and when one of us falls, the rest of us often follow. What am I?', '["A domino","A playing card","A matchstick","A coin"]', 0, 'A domino is one of many identical tiles in a set, and knocking one over in a line often causes the rest to fall too.'),
(3, 'riddle', 'I wave proudly without having any arms of my own, and I represent an entire country without ever saying a single word. What am I?', '["A banner","A flag","A shield","An emblem"]', 1, 'A flag waves in the wind with no arms of its own, and it symbolically represents a whole country in silence.'),
(3, 'riddle', 'I am a pattern made only of black and white lines, and a scanner reads my hidden secret to find a price. What am I?', '["A QR code","A barcode","A serial number","A receipt"]', 1, 'A barcode is a pattern of black and white lines that a scanner reads to instantly look up a product''s price.');
insert into questions (level, category, question_text, options, correct_option_index, explanation) values
(3, 'spatial', 'A cube has 6 faces. How many pairs of faces are directly opposite each other?', '["2","3","4","6"]', 1, 'A cube''s 6 faces form 3 opposite pairs: top/bottom, left/right, and front/back.'),
(3, 'spatial', 'How many faces does a rectangular box (cuboid) have?', '["4","6","8","12"]', 1, 'A rectangular box has 6 faces: top, bottom, and the 4 sides.'),
(3, 'spatial', 'A regular tetrahedron has all of its faces as equilateral triangles. How many faces does it have?', '["3","4","5","6"]', 1, 'A regular tetrahedron is a triangular pyramid with exactly 4 triangular faces.'),
(3, 'spatial', 'You are facing North. You turn 90 degrees counter-clockwise, then turn another 90 degrees counter-clockwise. Which direction do you face now?', '["East","West","South","North"]', 2, 'Turning 90 degrees counter-clockwise from North faces West; turning another 90 degrees counter-clockwise from West faces South.'),
(3, 'spatial', 'A rectangular room is 6 meters long and 5 meters wide. What is its floor area?', '["25 sq m","30 sq m","35 sq m","11 sq m"]', 1, 'Area of a rectangle = length x width = 6 x 5 = 30 sq m.'),
(3, 'spatial', 'How many lines of symmetry does a regular hexagon have?', '["3","4","6","8"]', 2, 'A regular hexagon has 6 lines of symmetry - 3 through opposite corners and 3 through the midpoints of opposite sides.'),
(3, 'spatial', 'A rectangular flag is folded in half twice, corner to corner each time, forming a smaller triangle. How many layers of fabric thick is the folded flag?', '["2","3","4","8"]', 2, 'Each fold doubles the number of layers: 1 layer becomes 2 after the first fold, then 4 after the second fold.'),
(3, 'spatial', 'A cube is sliced exactly in half with a single flat cut parallel to one of its faces. What shape is the flat cross-section?', '["A square","A triangle","A rectangle (non-square)","A circle"]', 0, 'Cutting a cube parallel to one of its faces exposes a cross-section identical in shape to that face - a square.'),
(3, 'spatial', 'A rectangular block (not a cube) is sliced in half with a flat cut parallel to its shortest face. What shape is the cross-section?', '["A square","A rectangle","A triangle","A circle"]', 1, 'A cut parallel to a face always exposes a shape matching that face - since the block is not a cube, that face (and the cross-section) is a rectangle.'),
(3, 'spatial', 'How many vertices (corners) does a triangular prism have?', '["4","5","6","8"]', 2, 'A triangular prism has 2 triangular faces, each with 3 corners, giving 6 vertices in total.'),
(3, 'spatial', 'A square has a side length of 9 cm. What is its perimeter?', '["18 cm","27 cm","36 cm","81 cm"]', 2, 'Perimeter of a square = 4 x side length = 4 x 9 = 36 cm.'),
(3, 'spatial', 'A circle has a radius of 7 cm. Using pi = 22/7, what is its approximate circumference?', '["22 cm","44 cm","49 cm","154 cm"]', 1, 'Circumference = 2 x pi x radius = 2 x (22/7) x 7 = 44 cm.'),
(3, 'spatial', 'You walk 6 steps East, then 8 steps North. How far are you, in a straight line, from your starting point?', '["10 steps","12 steps","14 steps","8 steps"]', 0, 'This forms a right triangle with legs 6 and 8. The straight-line distance is the hypotenuse: the square root of (6 squared + 8 squared) = the square root of 100 = 10 steps.'),
(3, 'spatial', 'A wheel has a diameter of 14 cm. Using pi = 22/7, how far does it travel in one full rotation?', '["22 cm","28 cm","44 cm","88 cm"]', 2, 'The distance traveled in one rotation equals the circumference: pi x diameter = (22/7) x 14 = 44 cm.'),
(3, 'spatial', 'How many edges does a triangular prism have?', '["6","9","12","15"]', 1, 'A triangular prism has 3 edges on the top triangle, 3 on the bottom triangle, and 3 connecting them vertically, for 9 edges total.'),
(3, 'spatial', 'If you rotate the capital letter S by 180 degrees, what does it look like?', '["Still looks like S","Looks like Z","Looks like the number 2","Looks like a backwards S"]', 0, 'The letter S has point symmetry, so rotating it 180 degrees makes it look exactly the same as before.'),
(3, 'spatial', 'A rectangular swimming pool is twice as long as it is wide. If the width is 5 meters, what is the pool''s area?', '["25 sq m","40 sq m","50 sq m","100 sq m"]', 2, 'The length is 2 x 5 = 10 meters, so the area is 10 x 5 = 50 sq m.'),
(3, 'spatial', 'If you look directly at exactly one corner of a cube (with the cube otherwise transparent), how many of its square faces can you see meeting at that corner?', '["1","2","3","4"]', 2, 'Exactly 3 faces meet at any single corner (vertex) of a cube, and all 3 are visible when looking straight at that corner.'),
(3, 'spatial', 'How many sides does a regular octagon have?', '["6","7","8","9"]', 2, 'The prefix octa- means eight, so a regular octagon has 8 equal sides.'),
(3, 'spatial', 'If a circular piece of paper is folded exactly in half three times in a row, into how many equal wedge-shaped sections does it end up divided?', '["4","6","8","16"]', 2, 'Each fold doubles the number of sections: 2, then 4, then 8 after three folds.'),
(3, 'spatial', 'A triangle has two angles measuring 50 degrees and 60 degrees. What is the measure of its third angle?', '["60 degrees","65 degrees","70 degrees","80 degrees"]', 2, 'The angles in any triangle add up to 180 degrees, so the third angle is 180 - 50 - 60 = 70 degrees.'),
(3, 'spatial', 'A rectangular picture frame measures 30 cm by 20 cm on the outside, with a 2 cm wide border running all the way around. What are the dimensions of the picture inside the border?', '["28 x 18 cm","26 x 16 cm","24 x 14 cm","30 x 20 cm"]', 1, 'The border takes 2 cm off each side, meaning 4 cm off each dimension in total: (30 - 4) by (20 - 4) = 26 by 16 cm.'),
(3, 'spatial', 'Five identical cubes are stacked directly on top of each other in a single vertical tower. How many cube faces are completely hidden, touching another cube?', '["4","6","8","10"]', 2, 'Between 5 stacked cubes there are 4 points of contact, and each contact hides 2 faces (one from each cube): 4 x 2 = 8.'),
(3, 'spatial', 'A right triangle has legs measuring 6 cm and 8 cm. What is the length of its hypotenuse?', '["9 cm","10 cm","12 cm","14 cm"]', 1, 'By the Pythagorean theorem, the hypotenuse is the square root of (6 squared + 8 squared) = the square root of 100 = 10 cm.'),
(3, 'spatial', 'How many total planes of symmetry does a cube have?', '["3","6","9","12"]', 2, 'A cube has 9 planes of symmetry in total: 3 that cut it into two equal rectangular halves, and 6 that cut diagonally through pairs of opposite edges.'),
(3, 'spatial', 'If North is directly to your left, which direction are you currently facing?', '["North","South","East","West"]', 2, 'If you face East, North lies to your left and South lies to your right, matching the clue.'),
(3, 'spatial', 'A regular pentagon has interior angles that each measure how many degrees?', '["100 degrees","108 degrees","120 degrees","135 degrees"]', 1, 'The interior angles of any pentagon add up to (5-2) x 180 = 540 degrees. Divided equally among 5 angles, each is 108 degrees.'),
(3, 'spatial', 'A cone and a cylinder share the same base radius and the same height. How many times greater is the cylinder''s volume compared to the cone''s volume?', '["2 times","3 times","4 times","1.5 times"]', 1, 'A cone''s volume is exactly one third of a cylinder''s volume when they share the same base and height, so the cylinder''s volume is 3 times the cone''s.'),
(3, 'spatial', 'A map uses a scale of 1 cm = 5 km. How many kilometers does a 6 cm distance on the map represent?', '["11 km","25 km","30 km","36 km"]', 2, 'At a scale of 1 cm = 5 km, 6 cm represents 6 x 5 = 30 km.'),
(3, 'spatial', 'A square is drawn inside a circle so that all four of its corners touch the circle. If the square''s diagonal is 10 cm and equals the circle''s diameter, what is the circle''s radius?', '["5 cm","7.5 cm","10 cm","2.5 cm"]', 0, 'The radius is always half the diameter, so 10 cm / 2 = 5 cm.'),
(3, 'spatial', 'How many total corners (vertices) does a rectangular box (cuboid) have?', '["4","6","8","12"]', 2, 'A rectangular box has 8 corners - 4 on the top face and 4 directly below them on the bottom face.'),
(3, 'spatial', 'A ramp rises 3 meters over a horizontal distance of 4 meters. What is the length of the ramp''s slanted surface?', '["4 meters","5 meters","6 meters","7 meters"]', 1, 'By the Pythagorean theorem, the slanted length is the square root of (3 squared + 4 squared) = the square root of 25 = 5 meters.'),
(3, 'spatial', 'If you reflect the point (2, 3) across the vertical y-axis, what are its new coordinates?', '["(-2, 3)","(2, -3)","(-2, -3)","(3, 2)"]', 0, 'Reflecting across the y-axis flips the sign of the x-coordinate only, changing (2, 3) to (-2, 3).'),
(3, 'spatial', 'A regular pyramid has a hexagonal base. How many triangular side faces does it have?', '["4","5","6","8"]', 2, 'A pyramid always has one triangular side face for each side of its base, so a hexagonal base gives 6 triangular side faces.'),
(3, 'spatial', 'Two identical cubes are glued together face-to-face to form one solid. How many outer faces does the resulting solid have?', '["8","10","12","6"]', 1, 'Each cube has 6 faces (12 total), but the two glued-together faces are hidden inside, removing 2 from the count: 12 - 2 = 10.'),
(3, 'spatial', 'How many edges meet at each single vertex (corner) of a cube?', '["2","3","4","6"]', 1, 'At every corner of a cube, exactly 3 edges come together.'),
(3, 'spatial', 'A rectangular tile is 3 times as long as it is wide, and has a perimeter of 32 cm. What is the tile''s width?', '["2 cm","4 cm","6 cm","8 cm"]', 1, 'If the width is w, the length is 3w, and the perimeter is 2(w + 3w) = 8w = 32, so w = 4 cm.'),
(3, 'spatial', 'If you rotate a square by 45 degrees, what shape does its outline resemble to most people?', '["A diamond","A triangle","A pentagon","A circle"]', 0, 'A square rotated 45 degrees so its corners point up, down, left, and right is commonly described as looking like a diamond.'),
(3, 'spatial', 'A cube-shaped box has a volume of 125 cubic cm. What is the length of one of its edges?', '["4 cm","5 cm","6 cm","25 cm"]', 1, 'Since volume = edge cubed, the edge length is the cube root of 125, which is 5 cm.'),
(3, 'spatial', 'Not counting its 2 triangular ends, how many rectangular faces does a triangular prism have?', '["2","3","4","5"]', 1, 'A triangular prism has exactly 3 rectangular side faces connecting the two triangular ends.'),
(3, 'spatial', 'You are facing South, then you turn 270 degrees clockwise. Which direction do you now face?', '["North","East","South","West"]', 1, 'Starting at South (180 degrees) and adding 270 degrees clockwise gives 450 degrees, which wraps around to 90 degrees - East.'),
(3, 'spatial', 'A circular pizza is cut into 8 equal slices. What is the angle at the center for each slice?', '["30 degrees","36 degrees","45 degrees","60 degrees"]', 2, 'A full circle is 360 degrees, and dividing it into 8 equal slices gives 360 / 8 = 45 degrees per slice.'),
(3, 'spatial', 'How many faces meet at each single vertex of a regular octahedron?', '["3","4","5","6"]', 1, 'A regular octahedron has 4 triangular faces meeting at each of its 6 vertices.'),
(3, 'spatial', 'A rectangular box has a square base with 4 cm sides and a height of 10 cm. What is its total volume?', '["40 cubic cm","80 cubic cm","160 cubic cm","400 cubic cm"]', 2, 'Volume = length x width x height = 4 x 4 x 10 = 160 cubic cm.'),
(3, 'spatial', 'If you slice a cylinder with a flat cut perpendicular to its circular base, straight down through the middle, what shape is the cross-section?', '["A circle","A rectangle","A triangle","An oval"]', 1, 'A cut straight down through the middle of a cylinder, perpendicular to its base, exposes a flat rectangular cross-section.'),
(3, 'spatial', 'A rectangular garden measuring 8 m by 6 m is surrounded by a 1-meter-wide path on all sides. What is the total area including the path?', '["48 sq m","64 sq m","80 sq m","96 sq m"]', 2, 'The path adds 1 m to each side of each dimension, making the outer size 10 m by 8 m: 10 x 8 = 80 sq m.'),
(3, 'spatial', 'How many square faces does a square pyramid have (a pyramid with a square base)?', '["0","1","2","4"]', 1, 'A square pyramid has only 1 square face, its base - the 4 side faces are all triangles.'),
(3, 'spatial', 'Two identical right isosceles triangles (with two equal legs) are joined together along their longest side, the hypotenuse. What shape results?', '["A square","A pentagon","A hexagon","A circle"]', 0, 'Joining two right isosceles triangles hypotenuse-to-hypotenuse recreates the square they would form if you cut a square exactly along its diagonal.'),
(3, 'spatial', 'On a standard 6-sided number cube (die), the dots on any two opposite faces always add up to the same total. What is that total?', '["6","7","8","9"]', 1, 'On a standard die, opposite faces always add up to 7: 1 and 6, 2 and 5, and 3 and 4.'),
(3, 'spatial', 'A rectangular sheet of paper measuring 20 cm by 10 cm is rolled up so that its 20 cm side becomes the circular edge (circumference) of a cylinder. What is that circumference?', '["10 cm","15 cm","20 cm","30 cm"]', 2, 'Rolling the paper this way means the 20 cm side wraps all the way around to form the circle, so the circumference is exactly 20 cm.');
